window.IND_FEED_BODY = window.IND_FEED_BODY || {};
Object.assign(window.IND_FEED_BODY, {"st-pt.lion-rabbit":{"id":"st-pt.lion-rabbit","src":"story:pt.lion-rabbit:scenes:0:text","route":"#/story/pt.lion-rabbit","title":"The Lion Who Met Himself","body":"In the forest of Mandara there lived a lion called Bhasuraka. He was not hungry. That was the trouble. He killed for the fun of it, ten animals a day, and the forest was emptying out.","art":"art/story/pt-lion-rabbit.jpg","cta":"Read the story","why":"From Panchatantra"},"st-pt.monkey-crocodile":{"id":"st-pt.monkey-crocodile","src":"story:pt.monkey-crocodile:scenes:0:text","route":"#/story/pt.monkey-crocodile","title":"The Monkey Who Kept His Heart in a Tree","body":"On the bank of a wide river grew a jamun tree, heavy with purple fruit. In it lived a monkey who had more fruit than he could ever eat, and nobody to share it with.","art":"art/story/pt-monkey-crocodile.jpg","cta":"Read the story","why":"From Panchatantra"},"st-pt.talkative-tortoise":{"id":"st-pt.talkative-tortoise","src":"story:pt.talkative-tortoise:scenes:0:text","route":"#/story/pt.talkative-tortoise","title":"The Tortoise Who Had to Have the Last Word","body":"In a lake near Ujjain lived a tortoise named Kambugriva, and two geese who were his dearest friends. Kambugriva had exactly one fault. He could not stop talking. Not for a moment. Not for anything.","art":"art/story/pt-talkative-tortoise.jpg","cta":"Read the story","why":"From Panchatantra"},"st-pt.blue-jackal":{"id":"st-pt.blue-jackal","src":"story:pt.blue-jackal:scenes:0:text","route":"#/story/pt.blue-jackal","title":"The Jackal Who Turned Blue","body":"A hungry jackal called Chandarava crept into a town at night looking for scraps. The dogs found him first. He ran — through a gate, through a yard, and straight into a dyer's enormous vat.","art":"art/story/pt-blue-jackal.jpg","cta":"Read the story","why":"From Panchatantra"},"st-ab.shorter-line":{"id":"st-ab.shorter-line","src":"story:ab.shorter-line:scenes:0:text","route":"#/story/ab.shorter-line","title":"The Line Nobody Could Shorten","body":"The Emperor Akbar liked to set his court impossible problems, mostly because he liked watching Birbal solve them. One morning he drew a long line across the floor with a piece of chalk.","art":"art/story/ab-shorter-line.jpg","cta":"Read the story","why":"From Akbar & Birbal"},"st-ab.khichdi":{"id":"st-ab.khichdi","src":"story:ab.khichdi:scenes:0:text","route":"#/story/ab.khichdi","title":"Birbal's Khichdi","body":"It was the coldest week of the year. \"A thousand gold coins,\" announced Akbar, \"to anyone who can stand in the palace lake all night, up to his neck, with no fire and no blanket.\"","art":"art/story/ab-khichdi.jpg","cta":"Read the story","why":"From Akbar & Birbal"},"st-ab.crows":{"id":"st-ab.crows","src":"story:ab.crows:scenes:0:text","route":"#/story/ab.crows","title":"How Many Crows in the Kingdom?","body":"Akbar was watching crows squabble on the palace wall when a thought struck him. \"Birbal,\" he said. \"How many crows are there in my kingdom?\"","art":"art/story/ab-crows.jpg","cta":"Read the story","why":"From Akbar & Birbal"},"st-ka.ganesha-race":{"id":"st-ka.ganesha-race","src":"story:ka.ganesha-race:scenes:0:text","route":"#/story/ka.ganesha-race","title":"The Race Around the World","body":"A sage once brought a single golden mango to Kailash — a fruit of wisdom, meant for one person only. Shiva and Parvati had two sons: Ganesha, round and thoughtful, and Kartikeya, quick and fierce.","art":"art/story/ka-ganesha-race.jpg","cta":"Read the story","why":"From Great Stories"},"st-ka.hanuman-leap":{"id":"st-ka.hanuman-leap","src":"story:ka.hanuman-leap:scenes:0:text","route":"#/story/ka.hanuman-leap","title":"Hanuman's Leap","body":"Sita had been carried away across the water to Lanka. The army of vanaras stood on the last rock of the mainland and looked at a hundred miles of open sea, and every one of them knew they could not cross it.","art":"art/story/ka-hanuman-leap.jpg","cta":"Read the story","why":"From Great Stories"},"st-ka.buddha-mustard":{"id":"st-ka.buddha-mustard","src":"story:ka.buddha-mustard:scenes:0:text","route":"#/story/ka.buddha-mustard","title":"The Mustard Seed","body":"A woman called Kisa Gotami lost her only child. She would not accept it. She carried him through the town asking every single person for medicine to bring him back, and everyone turned away — until one old man said: \"Go to the Buddha.\"","art":"art/story/ka-buddha-mustard.jpg","cta":"Read the story","why":"From Great Stories"},"st-ka.mahavira-elephant":{"id":"st-ka.mahavira-elephant","src":"story:ka.mahavira-elephant:scenes:0:text","route":"#/story/ka.mahavira-elephant","title":"Six Blind Men and an Elephant","body":"Six men who had been blind from birth were brought to an elephant and asked to say what it was like. Each of them reached out and touched a different part.","art":"art/story/ka-mahavira-elephant.jpg","cta":"Read the story","why":"From Great Stories"},"st-fk.kiranmala":{"id":"st-fk.kiranmala","src":"story:fk.kiranmala:scenes:0:text","route":"#/story/fk.kiranmala","title":"Kiranmala and the Mountain of Voices","body":"This is a story Bengali grandmothers have been telling at bedtime for a very long time. In a village outside the city, an old potter once found three babies floating down the river in a wooden box.","art":"art/story/fk-kiranmala.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-wt.gopal-smell":{"id":"st-wt.gopal-smell","src":"story:wt.gopal-smell:scenes:0:text","route":"#/story/wt.gopal-smell","title":"Paying for the Smell","body":"There was a sweet-shop in the town with a doorway that smelled so good that people slowed down as they passed it. A poor man used to eat his dry roti sitting on the step outside, because dry roti eaten in that doorway tasted of hot jalebi.","art":"art/story/wt-gopal-smell.jpg","cta":"Read the story","why":"From The Clever Ones"},"st-wt.tenali-thieves":{"id":"st-wt.tenali-thieves","src":"story:wt.tenali-thieves:scenes:0:text","route":"#/story/wt.tenali-thieves","title":"The Thieves Who Watered the Garden","body":"Tenali Raman was the funniest man at the court of King Krishnadevaraya, which meant he was also, quietly, the cleverest. One hot night he was lying awake when he heard something in the garden that was not the wind: four men, whispering, going carefully through the plantains.","art":"art/story/wt-tenali-thieves.jpg","cta":"Read the story","why":"From The Clever Ones"},"st-ep.squirrel-bridge":{"id":"st-ep.squirrel-bridge","src":"story:ep.squirrel-bridge:scenes:0:text","route":"#/story/ep.squirrel-bridge","title":"The Squirrel Who Built the Bridge","body":"At the very tip of the south, where the land runs out, Rama's army was building a bridge across the sea to Lanka. The vanaras were carrying boulders the size of houses. Some of them were carrying actual hills.","art":"art/story/ep-squirrel-bridge.jpg","cta":"Read the story","why":"From More from the Epics"},"st-fk.mahabali":{"id":"st-fk.mahabali","src":"story:fk.mahabali:scenes:0:text","route":"#/story/fk.mahabali","title":"The King Who Comes Home Every Year","body":"Every year at Onam, houses all over Kerala lay out a pookalam — a carpet of flower petals on the ground by the front door, a new ring of colour each morning for ten days. Long snake boats race down the backwaters.","art":"art/story/fk-mahabali.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-fk.pabuji":{"id":"st-fk.pabuji","src":"story:fk.pabuji:scenes:0:text","route":"#/story/fk.pabuji","title":"Pabuji Leaves His Own Wedding","body":"In a village in the Thar desert, when the work is done and the night is cold, a singer called a bhopa unrolls a long painted cloth between two poles. It is called a phad.","art":"art/story/fk-pabuji.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-fk.lambikin":{"id":"st-fk.lambikin","src":"story:fk.lambikin:scenes:0:text","route":"#/story/fk.lambikin","title":"Lambikin and the Drumikin","body":"Once there was a Lambikin who was so pleased with the world that he skipped everywhere instead of walking. One morning he set off through the forest to his Granny's house, singing, because Granny always fed him far too much.","art":"art/story/fk-lambikin.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-sk.sacha-sauda":{"id":"st-sk.sacha-sauda","src":"story:sk.sacha-sauda:scenes:0:text","route":"#/story/sk.sacha-sauda","title":"The Truest Bargain","body":"Before we start: in this story you will hear about Guru Nanak, but you will not see him. Sikhs do not make pictures of the Gurus, so we do not either. You will see the Khanda instead — and everyone else in the story.","art":"art/story/sk-sacha-sauda.jpg","cta":"Read the story","why":"From The Guru's Way"},"st-sk.langar-akbar":{"id":"st-sk.langar-akbar","src":"story:sk.langar-akbar:scenes:0:text","route":"#/story/sk.langar-akbar","title":"The Emperor Sits on the Floor","body":"At Goindval, on the river Beas in Punjab, Guru Amar Das had made a rule and would not bend it for anybody: before you meet me, you eat. In the langar. Sitting on the floor in a row, with whoever else is there, off the same plate as everyone else.","art":"art/story/sk-langar-akbar.jpg","cta":"Read the story","why":"From The Guru's Way"},"st-fk.shivaji-baskets":{"id":"st-fk.shivaji-baskets","src":"story:fk.shivaji-baskets:scenes:0:text","route":"#/story/fk.shivaji-baskets","title":"The Baskets of Sweets","body":"In 1666 Shivaji rode north to Agra to meet the Emperor, with his young son Sambhaji beside him. The meeting went badly. When he tried to leave, he found that he could not: soldiers on the gate, soldiers on the road, soldiers who were extremely polite and would not move.","art":"art/story/fk-shivaji-baskets.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-fk.unfinished-hands":{"id":"st-fk.unfinished-hands","src":"story:fk.unfinished-hands:scenes:0:text","route":"#/story/fk.unfinished-hands","title":"The Carpenter Who Asked for a Closed Door","body":"At Puri, on the coast of Odisha, King Indradyumna wanted to build the greatest temple on that shore. He had the walls. He had the towers. What he did not have was what should stand inside them, and no stone he was offered was the right stone.","art":"art/story/fk-unfinished-hands.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-fk.naga-brothers":{"id":"st-fk.naga-brothers","src":"story:fk.naga-brothers:scenes:0:text","route":"#/story/fk.naga-brothers","title":"The Man, the Tiger and the Spirit","body":"High in the Naga hills, where the villages sit on the tops of the ridges and the clouds come in through the doorways, they tell this at the start of everything. The first mother had three sons. One was the Spirit. One was the Tiger. One was the Man.","art":"art/story/fk-naga-brothers.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-fk.khasi-sun":{"id":"st-fk.khasi-sun","src":"story:fk.khasi-sun:scenes:0:text","route":"#/story/fk.khasi-sun","title":"The Sun Who Would Not Come Out","body":"In the Khasi hills of Meghalaya — the wettest place on earth, where the clouds walk through the villages — the sun is a woman. Ka Sngi, they call her. The moon is her brother.","art":"art/story/fk-khasi-sun.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-fk.chakli-kagdo":{"id":"st-fk.chakli-kagdo","src":"story:fk.chakli-kagdo:scenes:0:text","route":"#/story/fk.chakli-kagdo","title":"The House of Wax and the House of Dung","body":"In a village in Saurashtra there lived a little sparrow and a crow, in the same neem tree, on branches that nearly touched. One hot morning in May the sparrow said the thing everybody in Gujarat says in May: \"The rains are coming. We need houses.\"","art":"art/story/fk-chakli-kagdo.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-fk.punyakoti":{"id":"st-fk.punyakoti","src":"story:fk.punyakoti:scenes:0:text","route":"#/story/fk.punyakoti","title":"The Cow Who Came Back","body":"This one is a song before it is a story. Children in Karnataka learn it by heart — *Dharani mandala madhyadolage* — and grown men have been known to go quiet when it is sung. It is about a cow called Punyakoti.","art":"art/story/fk-punyakoti.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-jn.bahubali":{"id":"st-jn.bahubali","src":"story:jn.bahubali:scenes:0:text","route":"#/story/jn.bahubali","title":"The Fist That Stopped","body":"Bharata and Bahubali were brothers. Their father had been a king and had given up being a king, and had divided everything between his sons, and for a while that worked. Then Bharata decided that every kingdom in the land ought to bow to him — including his little brother's.","art":"art/story/jn-bahubali.jpg","cta":"Read the story","why":"From Jain Stories"},"st-wt.tenali-dolls":{"id":"st-wt.tenali-dolls","src":"story:wt.tenali-dolls:scenes:0:text","route":"#/story/wt.tenali-dolls","title":"Three Dolls and a Piece of Thread","body":"A scholar came to the court of Krishnadevaraya from a long way off, with a velvet cloth and a small box, and the manner of a man who has already decided he is the cleverest person in the room.","art":"art/story/wt-tenali-dolls.jpg","cta":"Read the story","why":"From The Clever Ones"},"st-wt.gonu-brinjal":{"id":"st-wt.gonu-brinjal","src":"story:wt.gonu-brinjal:scenes:0:text","route":"#/story/wt.gonu-brinjal","title":"Gonu Jha and the Brinjal","body":"In Mithila, in north Bihar, they tell stories about Gonu Jha the way other places tell them about Birbal — a man at the Raja's court who was never quite as harmless as he looked.","art":"art/story/wt-gonu-brinjal.jpg","cta":"Read the story","why":"From The Clever Ones"},"st-jt.quails-net":{"id":"st-jt.quails-net","src":"story:jt.quails-net:scenes:0:text","route":"#/story/jt.quails-net","title":"The Quails Who Flew Off With the Net","body":"A hundred quails lived in a field, and a fowler used to come at dawn, whistle like a quail until they came to him, and throw his net over the lot of them. He did very well out of it. The quails did not.","art":"art/story/jt-quails-net.jpg","cta":"Read the story","why":"From Jataka Tales"},"st-jn.chandkaushik":{"id":"st-jn.chandkaushik","src":"story:jn.chandkaushik:scenes:0:text","route":"#/story/jn.chandkaushik","title":"The Snake Everybody Ran From","body":"The villagers caught up with him at the edge of the trees, all talking at once. \"Not that way. There is a serpent on that path — Chandkaushik. Look at the grass round his tree, it is burnt. Go round. It is only one day longer.\"","art":"art/story/jn-chandkaushik.jpg","cta":"Read the story","why":"From Jain Stories"},"st-wt.kashmir-carry":{"id":"st-wt.kashmir-carry","src":"story:wt.kashmir-carry:scenes:0:text","route":"#/story/wt.kashmir-carry","title":"Shall I Carry You, or Will You Carry Me?","body":"A king of Kashmir liked to walk about his country in ordinary clothes, because a king in ordinary clothes finds out things a king in a crown never will. One long afternoon he fell into step with a farmer going the same way along the road to the town.","art":"art/story/wt-kashmir-carry.jpg","cta":"Read the story","why":"From The Clever Ones"},"st-fk.lingo-song":{"id":"st-fk.lingo-song","src":"story:fk.lingo-song:scenes:0:text","route":"#/story/fk.lingo-song","title":"Lingo and the First Song","body":"The Gond people of central India — the forests and hills of Chhattisgarh and Madhya Pradesh — tell of Lingo, who came first and worked things out for everybody else. Most of what the Gonds have, the singers say, Lingo went and fetched.","art":"art/story/fk-lingo-song.jpg","cta":"Read the story","why":"From Tales from Every Corner"},"st-wt.vetala-tree":{"id":"st-wt.vetala-tree","src":"story:wt.vetala-tree:scenes:0:text","route":"#/story/wt.vetala-tree","title":"The Thing in the Tree","body":"King Vikramaditya of Ujjain had promised something to a monk, and being the sort of king he was, he had not asked enough questions first. The promise was this: go to the old tree at the edge of the wood on a night with no moon, and bring back the vetala that hangs in it.","art":"art/story/wt-vetala-tree.jpg","cta":"Read the story","why":"From The Clever Ones"},"st-jt.banyan-deer":{"id":"st-jt.banyan-deer","src":"story:jt.banyan-deer:scenes:0:text","route":"#/story/jt.banyan-deer","title":"The Deer Who Would Not Send Anyone Else","body":"The king of Benares hunted deer in his park every single morning, with horses and drums and a hundred men. The herds ran until they dropped. Far more deer were hurt in the running than were ever needed in the kitchen, and the park was becoming a miserable place to live.","art":"art/story/jt-banyan-deer.jpg","cta":"Read the story","why":"From Jataka Tales"},"st-jt.hare-moon":{"id":"st-jt.hare-moon","src":"story:jt.hare-moon:scenes:0:text","route":"#/story/jt.hare-moon","title":"The Hare in the Moon","body":"Four friends lived by a river: a monkey, a jackal, an otter, and a hare. The hare was the one who thought about things. One evening, with the full moon coming, he said: \"Tomorrow is a day for giving. If anybody comes past hungry, we feed them. Agreed?\"","art":"art/story/jt-hare-moon.jpg","cta":"Read the story","why":"From Jataka Tales"},"st-ep.yaksha-lake":{"id":"st-ep.yaksha-lake","src":"story:ep.yaksha-lake:scenes:0:text","route":"#/story/ep.yaksha-lake","title":"The Questions at the Lake","body":"The five Pandava brothers were living in the forest, a long way from any kingdom, and it was the end of a very hot day and they had run out of water. Nakula, the quickest, went off to look and found a lake so still it looked like a floor.","art":"art/story/ep-yaksha-lake.jpg","cta":"Read the story","why":"From More from the Epics"},"st-ep.bhima-hanuman":{"id":"st-ep.bhima-hanuman","src":"story:ep.bhima-hanuman:scenes:0:text","route":"#/story/ep.bhima-hanuman","title":"The Old Monkey on the Path","body":"High in the Himalaya, a flower came floating down a stream past the Pandavas' camp — a saugandhika, huge and pale, and it smelled like nothing else in the world. Draupadi picked it out of the water and said she would like some more.","art":"art/story/ep-bhima-hanuman.jpg","cta":"Read the story","why":"From More from the Epics"},"st-jt.golden-goose":{"id":"st-jt.golden-goose","src":"story:jt.golden-goose:scenes:0:text","route":"#/story/jt.golden-goose","title":"The Goose Who Gave Gold","body":"A man died and left behind a wife and three daughters and almost nothing else. They took in sewing. They ate small. Nobody in the house said out loud how thin the year was getting, because saying it would not have helped.","art":"art/story/jt-golden-goose.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.woodpecker-lion":{"id":"st-jt.woodpecker-lion","src":"story:jt.woodpecker-lion:scenes:0:text","route":"#/story/jt.woodpecker-lion","title":"The Bird Who Went Down the Lion's Throat","body":"A lion ate too fast, the way he always did, and something sharp went in sideways and stuck. He could not swallow. He could not roar. He lay under a tree with his eyes watering and made a small, undignified, whistling noise.","art":"art/story/jt-woodpecker-lion.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.elephant-dog":{"id":"st-jt.elephant-dog","src":"story:jt.elephant-dog:scenes:0:text","route":"#/story/jt.elephant-dog","title":"The Elephant Who Stopped Eating","body":"The king's elephant lived in a stable bigger than most houses, and was washed twice a day, and was given rice cooked with ghee. He was, by every measure anybody had, the luckiest elephant in the kingdom.","art":"art/story/jt-elephant-dog.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.nandivisala":{"id":"st-jt.nandivisala","src":"story:jt.nandivisala:scenes:0:text","route":"#/story/jt.nandivisala","title":"The Ox Who Would Not Be Shouted At","body":"A man raised a calf from a baby, feeding him by hand, talking to him the whole time about nothing in particular. The calf grew into an ox with shoulders like a doorway, and the two of them understood each other perfectly.","art":"art/story/jt-nandivisala.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.monkey-gardener":{"id":"st-jt.monkey-gardener","src":"story:jt.monkey-gardener:scenes:0:text","route":"#/story/jt.monkey-gardener","title":"The Monkeys Who Watered the Garden","body":"The king's pleasure garden was full of young saplings, planted in rows, each one about as tall as a child. The gardener had watered them every evening for a month, and they were just beginning to hold their leaves properly.","art":"art/story/jt-monkey-gardener.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.crocodile-rock":{"id":"st-jt.crocodile-rock","src":"story:jt.crocodile-rock:scenes:0:text","route":"#/story/jt.crocodile-rock","title":"The Rock That Answered Back","body":"There was a monkey who lived on one bank of a river and ate on the other, because the fruit trees were all on the far side. He crossed twice a day by the same route: bank, rock in the middle, island. Bank, rock, island. He could have done it with his eyes shut.","art":"art/story/jt-crocodile-rock.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.parrot-figtree":{"id":"st-jt.parrot-figtree","src":"story:jt.parrot-figtree:scenes:0:text","route":"#/story/jt.parrot-figtree","title":"The Parrot Who Stayed With the Tree","body":"On the bank of the Ganga stood a fig tree so old and so wide that a thousand birds lived in it. In fruiting season the noise was tremendous. There was always enough for everybody and a good deal squashed underfoot besides.","art":"art/story/jt-parrot-figtree.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.partridge-elders":{"id":"st-jt.partridge-elders","src":"story:jt.partridge-elders:scenes:0:text","route":"#/story/jt.partridge-elders","title":"Who Was Here First?","body":"Under one enormous banyan tree lived three friends: an elephant, a monkey and a partridge. They got on well most of the time, which is to say they got on well until somebody wanted the good shade.","art":"art/story/jt-partridge-elders.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.quail-fire":{"id":"st-jt.quail-fire","src":"story:jt.quail-fire:scenes:0:text","route":"#/story/jt.quail-fire","title":"The Chick Who Could Not Fly Yet","body":"In a nest on the forest floor sat a quail chick, days old, with wings the size of two rupee coins. His parents were out looking for food, which is what quail parents do all day long.","art":"art/story/jt-quail-fire.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.guttila-veena":{"id":"st-jt.guttila-veena","src":"story:jt.guttila-veena:scenes:0:text","route":"#/story/jt.guttila-veena","title":"The Music Teacher and His Best Student","body":"Guttila was the finest veena player in Benares, and he taught for nothing, because he thought charging for music was a strange thing to do. Students came to his house from a long way off and he fed them too.","art":"art/story/jt-guttila-veena.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.three-birds-king":{"id":"st-jt.three-birds-king","src":"story:jt.three-birds-king:scenes:0:text","route":"#/story/jt.three-birds-king","title":"The King Who Asked Three Birds","body":"A king out hunting once found three eggs in three different places on the same afternoon, and brought them home, and they hatched in his own rooms. Which is how the king of Benares ended up raising three birds as his children.","art":"art/story/jt-three-birds-king.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-jt.trees-together":{"id":"st-jt.trees-together","src":"story:jt.trees-together:scenes:0:text","route":"#/story/jt.trees-together","title":"The Tree That Stood Alone","body":"The old king of that forest called the trees together at the start of the season — which sounds odd, but this is a story told by the Buddha, and in his stories the trees have opinions.","art":"art/story/jt-trees-together.jpg","cta":"Read the story","why":"From More Jataka Tales"},"st-pt.mongoose-baby":{"id":"st-pt.mongoose-baby","src":"story:pt.mongoose-baby:scenes:0:text","route":"#/story/pt.mongoose-baby","title":"The Mongoose at the Door","body":"A man and his wife had a baby son, and in the same month they took in an orphaned mongoose kit, and the two of them grew up on the same floor. The mongoose slept curled against the cradle. He would not be moved from it.","art":"art/story/pt-mongoose-baby.jpg","cta":"Read the story","why":"From More Panchatantra"},"st-pt.four-friends":{"id":"st-pt.four-friends","src":"story:pt.four-friends:scenes:0:text","route":"#/story/pt.four-friends","title":"Four Friends and One Hunter","body":"Laghupatanaka the crow and Hiranyaka the mouse were friends, which every other crow and every other mouse thought was ridiculous. They moved together to a lake where Mantharaka the tortoise lived, and the three of them got on so well that afternoons went missing.","art":"art/story/pt-four-friends.jpg","cta":"Read the story","why":"From More Panchatantra"},"st-pt.mice-iron":{"id":"st-pt.mice-iron","src":"story:pt.mice-iron:scenes:0:text","route":"#/story/pt.mice-iron","title":"The Mice Who Ate the Iron","body":"A merchant's business went bad and he had to leave town to start again somewhere else. The one thing he owned that was worth anything was a great iron balance-beam, heavy as a man, and he could not carry it with him.","art":"art/story/pt-mice-iron.jpg","cta":"Read the story","why":"From More Panchatantra"},"st-pt.crane-crab":{"id":"st-pt.crane-crab","src":"story:pt.crane-crab:scenes:0:text","route":"#/story/pt.crane-crab","title":"The Crane Who Offered a Lift","body":"There was an old crane who had got too slow to fish properly, which is a serious problem when fishing is the only thing you do. He stood in the shallows all day catching nothing and getting thinner and crosser.","art":"art/story/pt-crane-crab.jpg","cta":"Read the story","why":"From More Panchatantra"},"st-pt.elephants-rabbits":{"id":"st-pt.elephants-rabbits","src":"story:pt.elephants-rabbits:scenes:0:text","route":"#/story/pt.elephants-rabbits","title":"The Rabbit Who Spoke for the Moon","body":"The rains failed for two years and the forest ponds went to cracked mud. The only water for a day's walk was Chandra-sarovar — Moon Lake — and around Moon Lake, in the soft sandy ground, lived several hundred rabbits in burrows.","art":"art/story/pt-elephants-rabbits.jpg","cta":"Read the story","why":"From More Panchatantra"},"st-pt.two-headed-bird":{"id":"st-pt.two-headed-bird","src":"story:pt.two-headed-bird:scenes:0:text","route":"#/story/pt.two-headed-bird","title":"The Bird With Two Heads","body":"On a riverbank there lived a bird called Bharunda who had one body, one stomach, two long necks and two heads. Both heads could talk. Both heads had opinions. It was, on the whole, a companionable way to live.","art":"art/story/pt-two-headed-bird.jpg","cta":"Read the story","why":"From More Panchatantra"},"st-pt.lion-makers":{"id":"st-pt.lion-makers","src":"story:pt.lion-makers:scenes:0:text","route":"#/story/pt.lion-makers","title":"The Four Clever Men and the Lion","body":"Four young men set out from the same town to make their fortunes. Three of them had studied for years and could do genuinely astonishing things. The fourth had not studied much at all, and the other three brought it up rather often.","art":"art/story/pt-lion-makers.jpg","cta":"Read the story","why":"From More Panchatantra"},"st-pt.drum-jackal":{"id":"st-pt.drum-jackal","src":"story:pt.drum-jackal:scenes:0:text","route":"#/story/pt.drum-jackal","title":"The Thing That Boomed in the Bushes","body":"A jackal called Gomaya had gone three days without anything worth calling a meal, and hunger had made him bold in the way it does. He came out of the trees into an open field where an army had camped and moved on, leaving the usual mess behind.","art":"art/story/pt-drum-jackal.jpg","cta":"Read the story","why":"From More Panchatantra"},"st-pt.monkey-wedge":{"id":"st-pt.monkey-wedge","src":"story:pt.monkey-wedge:scenes:0:text","route":"#/story/pt.monkey-wedge","title":"The Monkey and the Wedge","body":"A temple was being built at the edge of town, and the yard was full of carpenters, and the carpenters were full of opinions, and the whole place was extremely interesting if you happened to be a monkey.","art":"art/story/pt-monkey-wedge.jpg","cta":"Read the story","why":"From More Panchatantra"},"st-pt.singing-donkey":{"id":"st-pt.singing-donkey","src":"story:pt.singing-donkey:scenes:0:text","route":"#/story/pt.singing-donkey","title":"The Donkey Who Wanted an Audience","body":"There was a washerman's donkey called Uddhata who worked all day and was fed extremely badly, and who had struck up a friendship with a jackal on the strength of it.","art":"art/story/pt-singing-donkey.jpg","cta":"Read the story","why":"From More Panchatantra"},"st-pu.samudra-manthan":{"id":"st-pu.samudra-manthan","src":"story:pu.samudra-manthan:scenes:0:text","route":"#/story/pu.samudra-manthan","title":"The Day They Churned the Sea","body":"This is one of the biggest stories there is, and it starts with something quite small: the devas had lost their strength, and everything they had ever been given had gone into the sea, and nobody could get it back out.","art":"art/story/pu-samudra-manthan.jpg","cta":"Read the story","why":"From Stories of the Gods"},"st-pu.ganga-shiva":{"id":"st-pu.ganga-shiva","src":"story:pu.ganga-shiva:scenes:0:text","route":"#/story/pu.ganga-shiva","title":"Catching a River in Your Hair","body":"A prince called Bhagiratha had one thing he wanted, and it was not a kingdom. His ancestors — sixty thousand of them, the story says, and stories are allowed to say things like that — had come to a bad end long ago, and their ashes had never been given water.","art":"art/story/pu-ganga-shiva.jpg","cta":"Read the story","why":"From Stories of the Gods"},"st-pu.durga-mahisha":{"id":"st-pu.durga-mahisha","src":"story:pu.durga-mahisha:scenes:0:text","route":"#/story/pu.durga-mahisha","title":"The One They All Made Together","body":"Mahishasura had been given a promise, and the promise was carefully worded the way these promises always are: no man and no god would be able to defeat him. He had checked. He had thought about it from every angle. He was, as far as he could see, finished with worrying.","art":"art/story/pu-durga-mahisha.jpg","cta":"Read the story","why":"From Stories of the Gods"},"st-pu.narasimha-prahlad":{"id":"st-pu.narasimha-prahlad","src":"story:pu.narasimha-prahlad:scenes:0:text","route":"#/story/pu.narasimha-prahlad","title":"The Boy Who Would Not Stop Saying the Name","body":"Hiranyakashipu had a promise too, and his was the most carefully written of all of them: he could not be killed by man or animal, indoors or outdoors, by day or by night, on the ground or in the air, by any weapon at all. He had thought about it for a very long time.","art":"art/story/pu-narasimha-prahlad.jpg","cta":"Read the story","why":"From Stories of the Gods"},"st-pu.dhruva-star":{"id":"st-pu.dhruva-star","src":"story:pu.dhruva-star:scenes:0:text","route":"#/story/pu.dhruva-star","title":"The Boy Who Became a Star","body":"King Uttanapada had two wives and two small sons, and he loved one household more easily than the other, which is a thing that happens in families and never stops hurting.","art":"art/story/pu-dhruva-star.jpg","cta":"Read the story","why":"From Stories of the Gods"},"st-pu.krishna-kaliya":{"id":"st-pu.krishna-kaliya","src":"story:pu.krishna-kaliya:scenes:0:text","route":"#/story/pu.krishna-kaliya","title":"The Boy Who Danced on the Snake","body":"There was a bend in the Yamuna at Vrindavan where the water had gone black and the trees on the bank had died, and the cows would not drink there, and the cowherd boys were told every single morning not to go anywhere near it.","art":"art/story/pu-krishna-kaliya.jpg","cta":"Read the story","why":"From Stories of the Gods"},"st-pu.govardhan":{"id":"st-pu.govardhan","src":"story:pu.govardhan:scenes:0:text","route":"#/story/pu.govardhan","title":"The Hill That Became an Umbrella","body":"Every year the cowherds of Vrindavan held a great offering to Indra, who sends the rain. It was the biggest day of their year. Carts of food, everybody's best clothes, weeks of cooking.","art":"art/story/pu-govardhan.jpg","cta":"Read the story","why":"From Stories of the Gods"},"st-pu.markandeya":{"id":"st-pu.markandeya","src":"story:pu.markandeya:scenes:0:text","route":"#/story/pu.markandeya","title":"The Boy Who Held On to the Stone","body":"Mrikandu and his wife had wanted a child for years, and when they were finally granted one they were asked a question first. Would you like an ordinary child who lives a long, ordinary life — or an extraordinary one who lives sixteen years?","art":"art/story/pu-markandeya.jpg","cta":"Read the story","why":"From Stories of the Gods"},"st-fk.bhekuli-biya":{"id":"st-fk.bhekuli-biya","src":"story:fk.bhekuli-biya:scenes:0:text","route":"#/story/fk.bhekuli-biya","title":"The Frogs' Wedding","body":"In Assam the rain is not something that might happen. It is the whole year. The Brahmaputra fills up, the paddy goes in, and the green comes up so fast you can practically watch it. Everything in the village calendar assumes the rain will arrive.","art":"art/story/fk-bhekuli-biya.jpg","cta":"Read the story","why":"From Corners Not Yet Lit"},"st-fk.lepcha-tower":{"id":"st-fk.lepcha-tower","src":"story:fk.lepcha-tower:scenes:0:text","route":"#/story/fk.lepcha-tower","title":"The Tower of Cooking Pots","body":"The Lepcha people call themselves Mutanchi Rongkup — the children of the snowy peak. The peak is Kanchenjunga, which stands over Sikkim, and in Lepcha tradition it is not scenery. It is family, and it is the guardian, and you do not climb to the top of your own grandfather.","art":"art/story/fk-lepcha-tower.jpg","cta":"Read the story","why":"From Corners Not Yet Lit"},"st-fk.pebet":{"id":"st-fk.pebet","src":"story:fk.pebet:scenes:0:text","route":"#/story/fk.pebet","title":"Pebet and the Cat","body":"In Manipur they tell about Pebet, a tiny brown bird, so small that when she puts her wings out she is about the size of your hand. She had six chicks in a nest low in the grass, and she fed them all day and half the night.","art":"art/story/fk-pebet.jpg","cta":"Read the story","why":"From Corners Not Yet Lit"},"st-fk.hojagiri-pots":{"id":"st-fk.hojagiri-pots","src":"story:fk.hojagiri-pots:scenes:0:text","route":"#/story/fk.hojagiri-pots","title":"The Girls Who Danced on the Water Pots","body":"In the hills of Tripura the Reang people — who call themselves Bru — grow their rice on the slopes, and when the harvest is in they thank Mailuma, who is the paddy: the one who decides whether there is rice in the basket or not.","art":"art/story/fk-hojagiri-pots.jpg","cta":"Read the story","why":"From Corners Not Yet Lit"},"st-fk.parashuram-coast":{"id":"st-fk.parashuram-coast","src":"story:fk.parashuram-coast:scenes:0:text","route":"#/story/fk.parashuram-coast","title":"The Arrow That Made the Coast","body":"Look at a map of the west coast of India. There is a wall of mountains — the Sahyadri, the Western Ghats — and then a thin green strip, and then the sea. That strip is the Konkan, and Goa sits in the middle of it, and this is the story Goa tells about where it came from.","art":"art/story/fk-parashuram-coast.jpg","cta":"Read the story","why":"From Corners Not Yet Lit"},"st-fk.hadimba-cedar":{"id":"st-fk.hadimba-cedar","src":"story:fk.hadimba-cedar:scenes:0:text","route":"#/story/fk.hadimba-cedar","title":"The Grandmother in the Cedar Wood","body":"Above Manali, in the Kullu valley of Himachal, there is a wood of deodar cedars so old and so dark that the light comes down through them in bars. In the middle of it stands a wooden temple with a roof like a pagoda, and it belongs to Hadimba.","art":"art/story/fk-hadimba-cedar.jpg","cta":"Read the story","why":"From Corners Not Yet Lit"},"st-fk.santhal-first-birds":{"id":"st-fk.santhal-first-birds","src":"story:fk.santhal-first-birds:scenes:0:text","route":"#/story/fk.santhal-first-birds","title":"The Two Birds and the First Morning","body":"The Santhals — who live across Jharkhand and the country round about, and who tell their history in songs at the start of the harvest — begin at the beginning, and the beginning is water. All water. Nothing else at all.","art":"art/story/fk-santhal-first-birds.jpg","cta":"Read the story","why":"From Corners Not Yet Lit"},"st-fk.karaikal-mango":{"id":"st-fk.karaikal-mango","src":"story:fk.karaikal-mango:scenes:0:text","route":"#/story/fk.karaikal-mango","title":"The Second Mango","body":"In Karaikal — which is on the coast, and is part of Puducherry today — there lived a woman called Punitavati.","art":"art/story/fk-karaikal-mango.jpg","cta":"Read the story","why":"From Corners Not Yet Lit"},"st-fk.andaman-fire":{"id":"st-fk.andaman-fire","src":"story:fk.andaman-fire:scenes:0:text","route":"#/story/fk.andaman-fire","title":"The Bird Who Carried the Fire","body":"The Andaman Islands are a long way out in the Bay of Bengal — closer to Myanmar than to the Indian mainland — and the peoples of those islands have been there for a very, very long time.","art":"art/story/fk-andaman-fire.jpg","cta":"Read the story","why":"From Corners Not Yet Lit"},"st-fk.abotani-rice":{"id":"st-fk.abotani-rice","src":"story:fk.abotani-rice:scenes:0:text","route":"#/story/fk.abotani-rice","title":"Abo Tani and the First Handful","body":"Arunachal Pradesh is where the sun comes up first in India — the name means the land of dawn-lit mountains. Across a great stretch of it, the Adi, the Nyishi, the Apatani, the Galo and others all trace themselves back to the same person: Abo Tani, the first man. Abo means father.","art":"art/story/fk-abotani-rice.jpg","cta":"Read the story","why":"From Corners Not Yet Lit"},"st-fk.panthirukulam":{"id":"st-fk.panthirukulam","src":"story:fk.panthirukulam:scenes:0:text","route":"#/story/fk.panthirukulam","title":"Twelve Houses, One Mother","body":"This is one of the oldest stories Kerala tells about itself, and once you have heard it you will see it everywhere you look there.","art":"art/story/fk-panthirukulam.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.naranath-boulder":{"id":"st-fk.naranath-boulder","src":"story:fk.naranath-boulder:scenes:0:text","route":"#/story/fk.naranath-boulder","title":"The Man Who Rolled the Boulder Up","body":"You remember the twelve children of one mother? This is the one who never settled anywhere. His name was Naranath, and all of Kerala called him Naranath Branthan — Naranath the mad one — and Kerala has been arguing for hundreds of years about whether that name was fair.","art":"art/story/fk-naranath-boulder.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.kochunni":{"id":"st-fk.kochunni","src":"story:fk.kochunni:scenes:0:text","route":"#/story/fk.kochunni","title":"The Man the Poor Would Not Give Up","body":"In Kayamkulam, in the backwater country of old Travancore, there was once a boy called Kochunni who was poor in the way that has no cushion under it at all. He swept a shopkeeper's floor for his food, and he was quick, and he watched everything.","art":"art/story/fk-kochunni.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.kathanar":{"id":"st-fk.kathanar","src":"story:fk.kathanar:scenes:0:text","route":"#/story/fk.kathanar","title":"The Priest Who Talked to the Dark","body":"Christians have lived in Kerala for a very, very long time — longer than in most of Europe, they will tell you, and proudly. At Kadamattom, among low green hills, stands one of their old churches, and this story belongs to it: the story of its most famous priest.","art":"art/story/fk-kathanar.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.theyyam-mirror":{"id":"st-fk.theyyam-mirror","src":"story:fk.theyyam-mirror:scenes:0:text","route":"#/story/fk.theyyam-mirror","title":"The Night Grandfather Became a Goddess","body":"In the far north of Kerala — Kannur, Kasaragod, the country they call Malabar — the gods do not wait to be visited. Once a year, in the cool season, they come to the village themselves, and they come dancing. It is called theyyam, and there is nothing else quite like it anywhere.","art":"art/story/fk-theyyam-mirror.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.aranmula-boat":{"id":"st-fk.aranmula-boat","src":"story:fk.aranmula-boat:scenes:0:text","route":"#/story/fk.aranmula-boat","title":"The Race That Nobody Must Win","body":"On the banks of the river Pampa stands the temple of Aranmula, where Krishna is worshipped as Parthasarathy — Arjuna's charioteer, the friend who steers. Remember that it is the steering-friend who lives here. It matters to how this story ends.","art":"art/story/fk-aranmula-boat.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.cheraman-moon":{"id":"st-fk.cheraman-moon","src":"story:fk.cheraman-moon:scenes:0:text","route":"#/story/fk.cheraman-moon","title":"The King Who Followed the Moon","body":"This is the story Kerala's Muslims tell about how their faith first came home to India, and it is theirs, and it is told here the way they tell it — with love.","art":"art/story/fk-cheraman-moon.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.avvaiyar-naaval":{"id":"st-fk.avvaiyar-naaval","src":"story:fk.avvaiyar-naaval:scenes:0:text","route":"#/story/fk.avvaiyar-naaval","title":"The Fruit That Needed Blowing On","body":"Avvaiyar was old before most stories about her even begin — a white-haired poet who walked the whole Tamil country on her own two feet, owning nothing but her verses. Kings stood up when she came in. Tamil children still learn her sayings before they learn almost anything else.","art":"art/story/fk-avvaiyar-naaval.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.kannagi-anklet":{"id":"st-fk.kannagi-anklet","src":"story:fk.kannagi-anklet:scenes:0:text","route":"#/story/fk.kannagi-anklet","title":"The Anklet Full of Rubies","body":"In the great port city of Puhar, where the Kaveri meets the eastern sea, there lived a young couple: Kannagi, patient and steady as a lamp flame, and her husband Kovalan, who was charming, and generous, and not very careful.","art":"art/story/fk-kannagi-anklet.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.karikala-kaveri":{"id":"st-fk.karikala-kaveri","src":"story:fk.karikala-kaveri:scenes:0:text","route":"#/story/fk.karikala-kaveri","title":"The Boy With the Fire-Marked Leg","body":"Long, long ago in the Chola country — so long ago that this was already an old story when most old stories were new — a king's story ended while his son was still a small boy.","art":"art/story/fk-karikala-kaveri.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.obavva-onake":{"id":"st-fk.obavva-onake","src":"story:fk.obavva-onake:scenes:0:text","route":"#/story/fk.obavva-onake","title":"Obavva and the Crack in the Rocks","body":"Chitradurga is a fort like a stone wave — seven rings of wall climbing over enormous round granite hills, in the dry heart of Karnataka. In the days this story happened, an enemy army had camped outside it for months, trying gate after gate, and getting nowhere.","art":"art/story/fk-obavva-onake.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.gullakayajji":{"id":"st-fk.gullakayajji","src":"story:fk.gullakayajji:scenes:0:text","route":"#/story/fk.gullakayajji","title":"The Grandmother's Little Cup of Milk","body":"At Shravanabelagola in Karnataka, on top of a bare granite hill, stands one of the wonders of the world: Bahubali — Gommateshwara — carved from a single stone, so tall that clouds seem to brush his shoulders, standing so perfectly still that the sculptors carved vines twining up his legs.","art":"art/story/fk-gullakayajji.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.kaveri-pot":{"id":"st-fk.kaveri-pot","src":"story:fk.kaveri-pot:scenes:0:text","route":"#/story/fk.kaveri-pot","title":"The River in the Sage's Pot","body":"High in the misty hills of Kodagu — Coorg, the coffee country of Karnataka — there is a small spring on a mountainside called Talakaveri: \"the head of the Kaveri.\" A whole great river starts there, in a pool you could step across. And this is the story of how she got out.","art":"art/story/fk-kaveri-pot.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.story-song":{"id":"st-fk.story-song","src":"story:fk.story-song:scenes:0:text","route":"#/story/fk.story-song","title":"The Story That Wanted Out","body":"In a village in the Kannada country there lived a woman who knew exactly one story and one song — her own grandmother had given them to her, mouth to ear, the way you hand over jewellery. And somehow, she had never once told them. There was cooking. There was the buffalo.","art":"art/story/fk-story-song.jpg","cta":"Read the story","why":"From The Deep South"},"st-wt.tenali-vikatakavi":{"id":"st-wt.tenali-vikatakavi","src":"story:wt.tenali-vikatakavi:scenes:0:text","route":"#/story/wt.tenali-vikatakavi","title":"The Boy Who Made the Goddess Laugh","body":"In the town of Tenali, in the green delta country of Andhra, there lived a boy called Rama — poor, fatherless, and with a tongue so quick that his mother despaired of him at least once a day. The world would come to know him as Tenali Raman, the funniest man in the south.","art":"art/story/wt-tenali-vikatakavi.jpg","cta":"Read the story","why":"From The Clever Ones"},"st-wt.tenali-book":{"id":"st-wt.tenali-book","src":"story:wt.tenali-book:scenes:0:text","route":"#/story/wt.tenali-book","title":"The Book That Did Not Exist","body":"A visiting scholar arrived at the great court of Krishnadevaraya, trailing servants and certificates. He had, he announced, defeated the best minds of every kingdom from the mountains to the sea, and he would debate anyone present on any book ever written. Any book at all.","art":"art/story/wt-tenali-book.jpg","cta":"Read the story","why":"From The Clever Ones"},"st-fk.paramananda-count":{"id":"st-fk.paramananda-count","src":"story:fk.paramananda-count:scenes:0:text","route":"#/story/fk.paramananda-count","title":"The Disciple Who Was Always Missing","body":"In the Telugu country there once lived a guru called Paramanandayya, a man of truly bottomless patience — which was fortunate, because his ten disciples were devoted, hardworking, and magnificently, dazzlingly foolish.","art":"art/story/fk-paramananda-count.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.srikalahasti":{"id":"st-fk.srikalahasti","src":"story:fk.srikalahasti:scenes:0:text","route":"#/story/fk.srikalahasti","title":"The Spider, the Snake and the Elephant","body":"Long before there was a town, in the forest by the river Swarnamukhi — \"the golden-faced river\" of Andhra — there stood a shivalinga under the trees, with no priest, no bell, and no roof. Just stone, and quiet.","art":"art/story/fk-srikalahasti.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.lepakshi":{"id":"st-fk.lepakshi","src":"story:fk.lepakshi:scenes:0:text","route":"#/story/fk.lepakshi","title":"Rise, Bird","body":"You know the terrible turn of the Ramayana: Sita, carried away south through the sky. What you may not know is that one creature tried to stop it. Jatayu — the great eagle-king, huge and old, who had been mighty once and had been Rama's father's friend.","art":"art/story/fk-lepakshi.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.poompuhar-sea":{"id":"st-fk.poompuhar-sea","src":"story:fk.poompuhar-sea:scenes:0:text","route":"#/story/fk.poompuhar-sea","title":"The City Under the Sea","body":"The long east coast of the south is called the Coromandel, and Karaikal — the sea-side piece of Puducherry — keeps its own stretch of it: fishing boats, casuarina trees, surf you can hear from your bed.","art":"art/story/fk-poompuhar-sea.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.amudha-surabhi":{"id":"st-fk.amudha-surabhi","src":"story:fk.amudha-surabhi:scenes:0:text","route":"#/story/fk.amudha-surabhi","title":"The Bowl That Was Never Empty","body":"Before the sea took Puhar back — you have heard that story — the city had one more tale to give the coast, and it is this one. It is about a girl called Manimekalai, a famous dancer's daughter, who was supposed to grow up to be a famous dancer herself.","art":"art/story/fk-amudha-surabhi.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.thirunallar-nala":{"id":"st-fk.thirunallar-nala","src":"story:fk.thirunallar-nala:scenes:0:text","route":"#/story/fk.thirunallar-nala","title":"The King Who Waited Out the Storm","body":"King Nala was one of the genuinely good ones — brave, fair, married to the wise and steadfast Damayanti, and, of all things, the finest cook among the kings of his age. His story is old enough to be told inside the Mahabharata itself.","art":"art/story/fk-thirunallar-nala.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.agastya-south":{"id":"st-fk.agastya-south","src":"story:fk.agastya-south:scenes:0:text","route":"#/story/fk.agastya-south","title":"The Small Sage Who Balanced the World","body":"When Shiva married Parvati in the high Himalaya, absolutely everyone went. Gods, sages, spirits, rivers in their travelling shapes — all of creation packed itself into the mountains of the north for the wedding of the age. Which created a problem nobody had thought of. Weight.","art":"art/story/fk-agastya-south.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.gautami-yanam":{"id":"st-fk.gautami-yanam","src":"story:fk.gautami-yanam:scenes:0:text","route":"#/story/fk.gautami-yanam","title":"The River That Washed a Sorrow","body":"In famine years, long ago, when the rains failed and failed again, there was exactly one green field left in the burnt country — on Brahmagiri hill in the western mountains, at the hermitage of the sage Gautama.","art":"art/story/fk-gautami-yanam.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.kadalamma":{"id":"st-fk.kadalamma","src":"story:fk.kadalamma:scenes:0:text","route":"#/story/fk.kadalamma","title":"The Sea Mother's Storeroom","body":"Mahe is the smallest and greenest piece of Puducherry — one river-mouth town tucked into the Malabar coast, speaking Malayalam, once flying a French flag, and if you ask for it by its older name, Mayyazhi, the whole town will know you mean home.","art":"art/story/fk-kadalamma.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.tittibha-sea":{"id":"st-fk.tittibha-sea","src":"story:fk.tittibha-sea:scenes:0:text","route":"#/story/fk.tittibha-sea","title":"The Birds Who Argued With the Sea","body":"In Pondicherry the whole town walks by the sea in the evening, along the promenade above the black rocks, and the sea booms away below like a big drum that never gets tired.","art":"art/story/fk-tittibha-sea.jpg","cta":"Read the story","why":"From The Deep South"},"st-fk.seven-cities":{"id":"st-fk.seven-cities","src":"story:fk.seven-cities:scenes:0:text","route":"#/story/fk.seven-cities","title":"The City Made of Cities","body":"A girl in Delhi asked her grandfather a simple question — how old is our city? — and instead of answering, he put on his walking shoes. \"Delhi is not one city,\" he said. \"It is a pile of cities. Come and count them.\"","art":"art/story/fk-seven-cities.jpg","cta":"Read the story","why":"From The Cities of Dilli"},"st-fk.iron-pillar":{"id":"st-fk.iron-pillar","src":"story:fk.iron-pillar:scenes:0:text","route":"#/story/fk.iron-pillar","title":"The Nail That Came Loose","body":"In the courtyard of the Qutb complex in Delhi stands an iron pillar, taller than four men, older than almost anything around it. Rain has fallen on it for more than fifteen hundred years. It has never rusted. Scientists still come to study why.","art":"art/story/fk-iron-pillar.jpg","cta":"Read the story","why":"From The Cities of Dilli"},"st-it.razia-sultan":{"id":"st-it.razia-sultan","src":"story:it.razia-sultan:scenes:0:text","route":"#/story/it.razia-sultan","title":"The Ruler Nobody Expected","body":"Almost eight hundred years ago, Delhi was ruled by Sultan Iltutmish, who had many sons and one daughter, Razia. The sons were princes and behaved like it. Razia sat with her father while he worked, and watched how a kingdom is actually run.","art":"art/story/it-razia-sultan.jpg","cta":"Read the story","why":"From The Cities of Dilli"},"st-fk.chandni-chowk":{"id":"st-fk.chandni-chowk","src":"story:fk.chandni-chowk:scenes:0:text","route":"#/story/fk.chandni-chowk","title":"The Square of Moonlight","body":"When Shah Jahan built his new city of Shahjahanabad — the Red Fort, the great mosque, the walls — the finest new bazaar in it was not designed by the emperor at all. It was designed by his daughter, Jahanara Begum.","art":"art/story/fk-chandni-chowk.jpg","cta":"Read the story","why":"From The Cities of Dilli"},"st-fk.kabootarbaz":{"id":"st-fk.kabootarbaz","src":"story:fk.kabootarbaz:scenes:0:text","route":"#/story/fk.kabootarbaz","title":"The Sky Over Old Delhi","body":"In the old city of Delhi, late in the afternoon, a boy climbed to his uncle's rooftop and found him standing at the edge, looking up, making a long call — aao, aao, aa — to nobody the boy could see.","art":"art/story/fk-kabootarbaz.jpg","cta":"Read the story","why":"From The Cities of Dilli"},"st-fk.ghalib-mangoes":{"id":"st-fk.ghalib-mangoes","src":"story:fk.ghalib-mangoes:scenes:0:text","route":"#/story/fk.ghalib-mangoes","title":"The Poet and the Mangoes","body":"A hundred and fifty-odd years ago, in a lane of Old Delhi called Ballimaran, lived Mirza Ghalib — a poet so good that people are still learning his verses by heart today, and will be long after all of us.","art":"art/story/fk-ghalib-mangoes.jpg","cta":"Read the story","why":"From The Cities of Dilli"},"st-fk.republic-day":{"id":"st-fk.republic-day","src":"story:fk.republic-day:scenes:0:text","route":"#/story/fk.republic-day","title":"The Morning the Whole Country Comes to One Road","body":"On the twenty-sixth of January, Delhi gets up in the dark. It is cold — proper Delhi-winter cold, the kind with fog in it — and families wrap up in shawls and monkey caps and head for one long, wide road with India Gate standing at the end of it.","art":"art/story/fk-republic-day.jpg","cta":"Read the story","why":"From The Cities of Dilli"},"st-it.hauz-khas":{"id":"st-it.hauz-khas","src":"story:it.hauz-khas:scenes:0:text","route":"#/story/it.hauz-khas","title":"The King Who Mended Things","body":"About seven hundred years ago, Sultan Alauddin Khalji built himself a new city at Delhi, called Siri. A city is thirsty, and Delhi's summers are merciless — so he had a vast tank dug nearby to catch the monsoon: the Hauz-i-Alai, the royal reservoir.","art":"art/story/it-hauz-khas.jpg","cta":"Read the story","why":"From The Cities of Dilli"},"st-it.nek-chand":{"id":"st-it.nek-chand","src":"story:it.nek-chand:scenes:0:text","route":"#/story/it.nek-chand","title":"The Secret Kingdom of Broken Things","body":"While Chandigarh was being built, a young roads inspector named Nek Chand cycled around the works every day. And everywhere he went, he saw what a rising city leaves behind: broken tiles, cracked pots, dead bulbs, smashed bangles, odd stones. Rubbish, everyone agreed.","art":"art/story/it-nek-chand.jpg","cta":"Read the story","why":"From The City Beautiful"},"st-fk.open-hand":{"id":"st-fk.open-hand","src":"story:fk.open-hand:scenes:0:text","route":"#/story/fk.open-hand","title":"The Hand That Turns With the Wind","body":"At the top of Chandigarh, where the government buildings stand in a great concrete plaza with the hills behind them, a girl on a school trip saw something strange against the sky: an enormous metal hand, high on a mast, open like a wave hello.","art":"art/story/fk-open-hand.jpg","cta":"Read the story","why":"From The City Beautiful"},"st-fk.sukhna-birds":{"id":"st-fk.sukhna-birds","src":"story:fk.sukhna-birds:scenes:0:text","route":"#/story/fk.sukhna-birds","title":"The Lake That Invites Winter Guests","body":"When Chandigarh was young, its makers looked at a seasonal stream called the Sukhna Choe, tumbling down from the Shivalik hills, and built an earthen dam across it. The stream pooled and spread and became a lake — Sukhna Lake, made by hands, on purpose.","art":"art/story/fk-sukhna-birds.jpg","cta":"Read the story","why":"From The City Beautiful"},"st-fk.rose-garden":{"id":"st-fk.rose-garden","src":"story:fk.rose-garden:scenes:0:text","route":"#/story/fk.rose-garden","title":"A City With Gardens for Rooms","body":"When the planners drew Chandigarh, they drew a ribbon of green running right through the middle of it, sector after sector, and wrote a rule beside it: this stays garden. Forever. No matter what.","art":"art/story/fk-rose-garden.jpg","cta":"Read the story","why":"From The City Beautiful"},"st-fk.village-before":{"id":"st-fk.village-before","src":"story:fk.village-before:scenes:0:text","route":"#/story/fk.village-before","title":"The Villages Under the Sectors","body":"A boy in Chandigarh once asked his great-grandmother the question every child of a new city asks eventually: \"What was here before?\" She looked at him for a moment, then pointed at the floor of the flat. \"Under this? Wheat,\" she said. \"I have cut wheat where your bed is.\"","art":"art/story/fk-village-before.jpg","cta":"Read the story","why":"From The City Beautiful"},"st-fk.chandi-name":{"id":"st-fk.chandi-name","src":"story:fk.chandi-name:scenes:0:text","route":"#/story/fk.chandi-name","title":"The Goddess the City Is Named For","body":"Every name is a little story folded up small. Take Chandigarh and unfold it: Chandi-garh. The fort of Chandi. A brand-new city of concrete and roundabouts, carrying the name of a goddess.","art":"art/story/fk-chandi-name.jpg","cta":"Read the story","why":"From The City Beautiful"},"st-fk.tree-streets":{"id":"st-fk.tree-streets","src":"story:fk.tree-streets:scenes:0:text","route":"#/story/fk.tree-streets","title":"The City That Planted Its Own Calendar","body":"When Chandigarh was planned, the trees were planned too — and not casually. The planners chose species avenue by avenue, like an artist choosing colours from a paintbox, and planted each road with its own kind of tree, thousands of them, before many of the houses even had roofs.","art":"art/story/fk-tree-streets.jpg","cta":"Read the story","why":"From The City Beautiful"},"st-fk.kullu-dussehra":{"id":"st-fk.kullu-dussehra","src":"story:fk.kullu-dussehra:scenes:0:text","route":"#/story/fk.kullu-dussehra","title":"The Festival Where the Gods Travel","body":"In the Kullu valley of Himachal, nearly every village has its own devta — its own deity, who lives in the village temple, knows the village's business, and is consulted like a wise elder. This is not a story from long ago. It is how the valley works today.","art":"art/story/fk-kullu-dussehra.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-fk.gaddi-dog":{"id":"st-fk.gaddi-dog","src":"story:fk.gaddi-dog:scenes:0:text","route":"#/story/fk.gaddi-dog","title":"The Shepherd's Other Shepherd","body":"The Gaddis are the shepherd people of Himachal, from the Dhauladhar country around Bharmour and Kangra. Twice a year they walk their flocks over the high passes — up to the summer meadows, down before the snow — living for months on the move.","art":"art/story/fk-gaddi-dog.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-fk.vipasha":{"id":"st-fk.vipasha","src":"story:fk.vipasha:scenes:0:text","route":"#/story/fk.vipasha","title":"The River That Unties Knots","body":"The Beas is born high in the mountains of Himachal, near the Rohtang pass, and comes down through the Kullu valley loud and green and cold, on its long way to the plains of Punjab. Rivers this old carry more than water. They carry names.","art":"art/story/fk-vipasha.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-it.apple-road":{"id":"st-it.apple-road","src":"story:it.apple-road:scenes:0:text","route":"#/story/it.apple-road","title":"The Man Who Brought the Apples","body":"A little more than a hundred years ago, a young American named Samuel Evans Stokes came from the city of Philadelphia to the hills of Himachal. He came to help at a home for sick people near Shimla — and the mountains did to him what mountains do to some people: they kept him.","art":"art/story/it-apple-road.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-fk.spiti-ghost":{"id":"st-fk.spiti-ghost","src":"story:fk.spiti-ghost:scenes:0:text","route":"#/story/fk.spiti-ghost","title":"The Grey Ghost of Spiti","body":"Spiti, in the far high corner of Himachal, is a cold desert — bare brown mountains, a ribbon of green along the river, villages of white houses under enormous silence. In winter it drops far below freezing and the silence gets even bigger.","art":"art/story/fk-spiti-ghost.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-fk.malana-sabha":{"id":"st-fk.malana-sabha","src":"story:fk.malana-sabha:scenes:0:text","route":"#/story/fk.malana-sabha","title":"The Village That Governs Itself","body":"Off the Kullu valley, up a steep side gorge, sits Malana — a village of stone and timber houses high above the river, reachable for most of its history only on foot. Its people speak their own language, Kanashi, spoken nowhere else on Earth.","art":"art/story/fk-malana-sabha.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-fk.kangra-brush":{"id":"st-fk.kangra-brush","src":"story:fk.kangra-brush:scenes:0:text","route":"#/story/fk.kangra-brush","title":"The Painters of the Small Monsoon","body":"Two hundred and some years ago, in the green Kangra valley under the Dhauladhar snows, there worked families of painters whose paintings were small enough to hold in two hands — and held, somehow, everything.","art":"art/story/fk-kangra-brush.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-fk.satisar":{"id":"st-fk.satisar","src":"story:fk.satisar:scenes:0:text","route":"#/story/fk.satisar","title":"The Valley That Was a Lake","body":"Long, long ago — so says Kashmir's own oldest telling — there was no valley of Kashmir at all. Between the ring of great mountains lay one enormous lake, vast and deep and cold, called Satisar, the lake of the goddess Sati.","art":"art/story/fk-satisar.jpg","cta":"Read the story","why":"From The Valley and the Lake"},"st-fk.himal-nagrai":{"id":"st-fk.himal-nagrai","src":"story:fk.himal-nagrai:scenes:0:text","route":"#/story/fk.himal-nagrai","title":"Himal and the Serpent Prince","body":"Kashmir is a valley of springs — cold, clear pools that rise out of the earth under the chinar trees. And Kashmiris have always said that springs are doors: that the naga folk, the serpent people of the old stories, live in shining kingdoms on the other side of the water.","art":"art/story/fk-himal-nagrai.jpg","cta":"Read the story","why":"From The Valley and the Lake"},"st-fk.lal-ded":{"id":"st-fk.lal-ded","src":"story:fk.lal-ded:scenes:0:text","route":"#/story/fk.lal-ded","title":"The Woman Everyone Claims","body":"Around seven hundred years ago, in the Kashmir valley, there lived a woman called Lalla. She had been married young into a house that was unkind to her, and one day — the tellings agree on this — she walked out of that life entirely, to seek God.","art":"art/story/fk-lal-ded.jpg","cta":"Read the story","why":"From The Valley and the Lake"},"st-fk.dal-morning":{"id":"st-fk.dal-morning","src":"story:fk.dal-morning:scenes:0:text","route":"#/story/fk.dal-morning","title":"The Lake That Is a Neighbourhood","body":"Before sunrise on Dal Lake, in Srinagar, the water is a sheet of grey silk with mountains standing round it — and out of the dark, from every direction, come boats. Long, slim wooden boats called shikaras, paddled with heart-shaped oars, loaded to the gunwales with vegetables.","art":"art/story/fk-dal-morning.jpg","cta":"Read the story","why":"From The Valley and the Lake"},"st-fk.boonyi-year":{"id":"st-fk.boonyi-year","src":"story:fk.boonyi-year:scenes:0:text","route":"#/story/fk.boonyi-year","title":"A Year Under the Chinar","body":"In Kashmiri it is called the boon; in books, the chinar. It is a plane tree, and in Kashmir it grows to a size that has to be seen to be believed — trunks wider than a room, crowns like green weather, some trees so old that Mughal emperors may have sat under them as saplings.","art":"art/story/fk-boonyi-year.jpg","cta":"Read the story","why":"From The Valley and the Lake"},"st-fk.kangri-winter":{"id":"st-fk.kangri-winter","src":"story:fk.kangri-winter:scenes:0:text","route":"#/story/fk.kangri-winter","title":"The Fire You Can Carry","body":"Kashmiri winter is serious winter — snow to the windowsills, icicles like fence posts, breath like smoke indoors. Its hardest stretch even has a name: Chillai Kalan, \"the great cold,\" forty days in the deep of winter when the valley truly freezes.","art":"art/story/fk-kangri-winter.jpg","cta":"Read the story","why":"From The Valley and the Lake"},"st-it.rakhigarhi":{"id":"st-it.rakhigarhi","src":"story:it.rakhigarhi:scenes:0:text","route":"#/story/it.rakhigarhi","title":"The Village on Top of a Lost City","body":"In Hisar district of Haryana there is a farming village called Rakhigarhi — buffaloes, wheat, brick houses, the usual weather. And beside and beneath it, a set of great dusty mounds, where children have always flown kites and grazed goats.","art":"art/story/it-rakhigarhi.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.akhara-pond":{"id":"st-fk.akhara-pond","src":"story:fk.akhara-pond:scenes:0:text","route":"#/story/fk.akhara-pond","title":"The Wrestlers by the Village Pond","body":"Every proper Haryana village has its johad — the village pond — where the buffaloes soak like glossy black islands and the herons do their slow patrolling. And near the pond, in village after village, there is something else: the akhara. The wrestling pit.","art":"art/story/fk-akhara-pond.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.surajkund":{"id":"st-fk.surajkund","src":"story:fk.surajkund:scenes:0:text","route":"#/story/fk.surajkund","title":"The Sun Pool Where India Comes to Sell Wonders","body":"In Faridabad, in southern Haryana, on the rocky old shoulders of the Aravalli hills, there is an ancient stone pool built in a great curve of steps — shaped, people have always said, like the rising sun. Its name says the same: Surajkund. The pool of the sun.","art":"art/story/fk-surajkund.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.kurukshetra-waters":{"id":"st-fk.kurukshetra-waters","src":"story:fk.kurukshetra-waters:scenes:0:text","route":"#/story/fk.kurukshetra-waters","title":"The Land Where the Gita Was Spoken","body":"Drive north through Haryana's wheat and mustard and you come to a name that makes the whole Mahabharata sit up: Kurukshetra. This ordinary-looking, extraordinary stretch of land is where tradition places the epic's great turning — and much more besides.","art":"art/story/fk-kurukshetra-waters.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.bail-race":{"id":"st-fk.bail-race","src":"story:fk.bail-race:scenes:0:text","route":"#/story/fk.bail-race","title":"The Race of the Two Bullock Carts","body":"They tell this one in the villages of Haryana, where a good pair of bullocks was once a family's tractor, truck and pride all in one, and where a bullock-cart race at fair time could keep the district in arguments for a year.","art":"art/story/fk-bail-race.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.charpai-darbar":{"id":"st-fk.charpai-darbar","src":"story:fk.charpai-darbar:scenes:0:text","route":"#/story/fk.charpai-darbar","title":"The Parliament Under the Banyan","body":"In the evening, when the buffaloes have been milked and the tools hung up, the charpais come out — the wooden-framed rope cots of the north — and are set down in the open, under the big banyan or beside somebody's gate, in a rough friendly circle.","art":"art/story/fk-charpai-darbar.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.dulla-bhatti":{"id":"st-fk.dulla-bhatti","src":"story:fk.dulla-bhatti:scenes:0:text","route":"#/story/fk.dulla-bhatti","title":"The Song Around the Lohri Fire","body":"On Lohri night, in the middle of the Punjabi winter, the bonfire goes up and the children go round the houses singing — and every child knows the song's first lines: Sundar mundriye, ho! Tera kaun vichara, ho! Dulla Bhatti wala, ho! Pretty girl, hey! Who will look out for you?","art":"art/story/fk-dulla-bhatti.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.sheikh-chilli-pot":{"id":"st-fk.sheikh-chilli-pot","src":"story:fk.sheikh-chilli-pot:scenes:0:text","route":"#/story/fk.sheikh-chilli-pot","title":"Sheikh Chilli Builds a Palace","body":"Sheikh Chilli — everyone in Punjab and Haryana knows Sheikh Chilli — was the greatest dreamer who ever lived. He never had two coins to rub together, but inside his head he was permanently, gloriously rich. His plans had plans.","art":"art/story/fk-sheikh-chilli-pot.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.sheikh-chilli-branch":{"id":"st-fk.sheikh-chilli-branch","src":"story:fk.sheikh-chilli-branch:scenes:0:text","route":"#/story/fk.sheikh-chilli-branch","title":"Sheikh Chilli and the Branch","body":"Sheikh Chilli needed firewood, and he needed it with the least possible effort, effort being a thing he saved carefully for emergencies. He picked a fine shady tree by the road, spotted a good thick branch, and climbed up with his saw between his teeth.","art":"art/story/fk-sheikh-chilli-branch.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.chiri-kaan":{"id":"st-fk.chiri-kaan","src":"story:fk.chiri-kaan:scenes:0:text","route":"#/story/fk.chiri-kaan","title":"The Sparrow, the Crow and the Khichdi","body":"Ik si chiri, ik si kaan — there was once a sparrow, there was once a crow. That is how the grandmothers of Punjab begin it, and every Punjabi child settles down at once, because they know exactly what is coming.","art":"art/story/fk-chiri-kaan.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.raja-rasalu":{"id":"st-fk.raja-rasalu","src":"story:fk.raja-rasalu:scenes:0:text","route":"#/story/fk.raja-rasalu","title":"The Prince Who Rode Out of the Story","body":"Long ago in Sialkot, in old Punjab, a son was born to King Salvahan — and the wise men read the stars and gave a strange instruction: for twelve years, the boy must not be seen abroad. So Rasalu grew up behind walls, in a palace with everything in it except the world.","art":"art/story/fk-raja-rasalu.jpg","cta":"Read the story","why":"From Fields of Punjab and Haryana"},"st-fk.ganga-yamuna-sisters":{"id":"st-fk.ganga-yamuna-sisters","src":"story:fk.ganga-yamuna-sisters:scenes:0:text","route":"#/story/fk.ganga-yamuna-sisters","title":"The Two Sisters Who Took Different Roads","body":"High in the mountains of Uttarakhand, closer together than you might think, two rivers are born. From the ice above Gangotri comes the Ganga. From the flanks of Bandarpunch, above Yamunotri, comes the Yamuna. One mountain neighbourhood; two beginnings.","art":"art/story/fk-ganga-yamuna-sisters.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-it.corbett":{"id":"st-it.corbett","src":"story:it.corbett:scenes:0:text","route":"#/story/it.corbett","title":"The Hunter Who Put Down His Rifle","body":"Jim Corbett was born about a hundred and fifty years ago in Nainital, in the Kumaon hills of what is now Uttarakhand, and grew up half-wild himself — a boy who spent every possible hour in the forest, until he could read it like a book and speak its language of alarm calls and silences.","art":"art/story/it-corbett.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-fk.bugyal-rules":{"id":"st-fk.bugyal-rules","src":"story:fk.bugyal-rules:scenes:0:text","route":"#/story/fk.bugyal-rules","title":"The Meadows Above the Trees","body":"Climb any big hill in Uttarakhand and the forest climbs with you — oak, then rhododendron, then deodar and fir — until, quite suddenly, the trees stop. Above that line the mountain wears open grass: rolling, cloud-brushed meadows called bugyals.","art":"art/story/fk-bugyal-rules.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-fk.nanda-raj-jat":{"id":"st-fk.nanda-raj-jat","src":"story:fk.nanda-raj-jat:scenes:0:text","route":"#/story/fk.nanda-raj-jat","title":"Walking the Goddess Home","body":"Over Garhwal and Kumaon stands Nanda Devi — one of the highest mountains in India, and much more than a mountain. To the hill people she is Nanda, the goddess — and, tenderly, she is also the hills' own daughter, married into the high snows.","art":"art/story/fk-nanda-raj-jat.jpg","cta":"Read the story","why":"From Stories from the High Hills"},"st-fk.cheraman-sails":{"id":"st-fk.cheraman-sails","src":"story:fk.cheraman-sails:scenes:0:text","route":"#/story/fk.cheraman-sails","title":"The Sailors Who Found the Islands","body":"Off the coast of Kerala, scattered over the blue like a handful of green beads, lie the islands of Lakshadweep — the smallest of all the places on India's map, and one of the loveliest. The islanders themselves tell a story about how anyone ever found them at all.","art":"art/story/fk-cheraman-sails.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.ubaidullah-lamp":{"id":"st-fk.ubaidullah-lamp","src":"story:fk.ubaidullah-lamp:scenes:0:text","route":"#/story/fk.ubaidullah-lamp","title":"The Dream That Crossed the Sea","body":"The people of Lakshadweep are Muslim, and have been for a very long time — the mosque is the middle of every island, the day is shaped by the five prayers, and the boats go out after the morning one.","art":"art/story/fk-ubaidullah-lamp.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.odam-race":{"id":"st-fk.odam-race","src":"story:fk.odam-race:scenes:0:text","route":"#/story/fk.odam-race","title":"Race Day on the Lagoon","body":"On Minicoy, the southernmost island of Lakshadweep, every village keeps a great racing boat, long and slim and polished like a musical instrument.","art":"art/story/fk-odam-race.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.minicoy-mahl":{"id":"st-fk.minicoy-mahl","src":"story:fk.minicoy-mahl:scenes:0:text","route":"#/story/fk.minicoy-mahl","title":"The Island That Speaks Mahl","body":"Most of the islands of Lakshadweep speak Malayalam, like the Kerala coast they came from. But sail south, past all the others, to the last island — Minicoy — and the language changes. Here the people speak Mahl.","art":"art/story/fk-minicoy-mahl.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.tuna-star":{"id":"st-fk.tuna-star","src":"story:fk.tuna-star:scenes:0:text","route":"#/story/fk.tuna-star","title":"One Fish at a Time","body":"Before first light on a Lakshadweep island, the tuna boat is already awake. The crew prays the dawn prayer, drinks something hot, and goes down to the water while the sky is still deciding what colour to be.","art":"art/story/fk-tuna-star.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.first-coconut":{"id":"st-fk.first-coconut","src":"story:fk.first-coconut:scenes:0:text","route":"#/story/fk.first-coconut","title":"The Nut That Crossed the Ocean","body":"Here is a tale for the smallest islands — the ones that began as nothing but a white sandbank on a coral reef, far out at sea, with no tree, no shade, no fresh water, and nobody home.","art":"art/story/fk-first-coconut.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.turtle-lagoon":{"id":"st-fk.turtle-lagoon","src":"story:fk.turtle-lagoon:scenes:0:text","route":"#/story/fk.turtle-lagoon","title":"The Turtle Who Kept the Lagoon Calm","body":"Every Lakshadweep island has two seas. Outside the reef is the big dark ocean, which is always in a hurry and always shouting. Inside the reef is the lagoon — green glass, warm as bathwater, so still you can watch a crab walk on the bottom from a boat.","art":"art/story/fk-turtle-lagoon.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.wandering-sandbank":{"id":"st-fk.wandering-sandbank","src":"story:fk.wandering-sandbank:scenes:0:text","route":"#/story/fk.wandering-sandbank","title":"The Sandbank That Goes Visiting","body":"Near one of the islands of Lakshadweep there is a sandbank — a little bare hill of white sand out in the lagoon, with no trees, no huts, no anything. On some days you can row out, land on it, and have the smallest country in the world all to yourself.","art":"art/story/fk-wandering-sandbank.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.tree-that-counts":{"id":"st-fk.tree-that-counts","src":"story:fk.tree-that-counts:scenes:0:text","route":"#/story/fk.tree-that-counts","title":"The Trees That Count as Family","body":"South of the Andamans, strung towards Sumatra, lie the Nicobar Islands — and they belong, first and always, to the Nicobarese, who have lived there for many centuries and still do.","art":"art/story/fk-tree-that-counts.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.ross-ficus":{"id":"st-fk.ross-ficus","src":"story:fk.ross-ficus:scenes:0:text","route":"#/story/fk.ross-ficus","title":"The Island the Roots Took Back","body":"Just off Port Blair in the Andamans lies a tiny island you can walk around in an hour. A hundred and some years ago, under British rule, it was the little capital of the whole island chain — Ross Island, where the officers who governed lived with their families.","art":"art/story/fk-ross-ficus.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.north-bay-light":{"id":"st-fk.north-bay-light","src":"story:fk.north-bay-light:scenes:0:text","route":"#/story/fk.north-bay-light","title":"The Lighthouse That Says Its Name","body":"At the mouth of the harbour near Port Blair, on a green headland called North Bay, stands a lighthouse — white and red-banded, above water so clear that the coral gardens below it are famous across India.","art":"art/story/fk-north-bay-light.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.dugong-meadow":{"id":"st-fk.dugong-meadow","src":"story:fk.dugong-meadow:scenes:0:text","route":"#/story/fk.dugong-meadow","title":"The Dugong Who Remembered","body":"Most people know the sea has fish. Fewer know the sea has meadows — real ones, of soft green seagrass, growing in the shallow sunlit water of quiet bays. And where there are meadows, there are grazers. In the Andaman and Nicobar Islands, the grazer is the dugong: the sea cow.","art":"art/story/fk-dugong-meadow.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.flying-fox-ferry":{"id":"st-fk.flying-fox-ferry","src":"story:fk.flying-fox-ferry:scenes:0:text","route":"#/story/fk.flying-fox-ferry","title":"The Evening Ferry of the Flying Foxes","body":"On the islands of the Andamans, the day ends with a show, and the show is free. Just as the sky goes gold, a long, slow, flapping line rises out of the tall trees and sets off across the water — hundreds of big dark shapes, unhurried as a ferry queue.","art":"art/story/fk-flying-fox-ferry.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.one-island-bird":{"id":"st-fk.one-island-bird","src":"story:fk.one-island-bird:scenes:0:text","route":"#/story/fk.one-island-bird","title":"The Bird With One Island","body":"Far out beyond the main Andaman Islands, alone in the open sea, stands a small green volcanic island called Narcondam. It has cliffs, forest, no town, and one resident that has made it famous among people who love birds: the Narcondam hornbill.","art":"art/story/fk-one-island-bird.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.island-of-tongues":{"id":"st-fk.island-of-tongues","src":"story:fk.island-of-tongues:scenes:0:text","route":"#/story/fk.island-of-tongues","title":"The Bazaar of Many Tongues","body":"Go to the morning market in Port Blair — the main town of the Andamans, lately given the new official name Sri Vijaya Puram — and just listen. Bengali at the fish stall. Tamil at the flower stall.","art":"art/story/fk-island-of-tongues.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.first-dance":{"id":"st-fk.first-dance","src":"story:fk.first-dance:scenes:0:text","route":"#/story/fk.first-dance","title":"How the First Evening Got Its Dance","body":"The Santhals of Jharkhand sing their whole history, from the very beginning of the world — and this is one of the tellings from early in that story, after the first ancestors, when their children and grandchildren had villages, and fields, and everything a people needs.","art":"art/story/fk-first-dance.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.singbonga-furnaces":{"id":"st-fk.singbonga-furnaces","src":"story:fk.singbonga-furnaces:scenes:0:text","route":"#/story/fk.singbonga-furnaces","title":"Sing Bonga and the Smoke That Hid the Sky","body":"The Munda people of Jharkhand, and their neighbours the Asur — who were master iron-smelters for centuries, real ones, whose old furnace mounds still dot the plateau — tell a story from the deep beginning of things, about iron, smoke, and the sun himself.","art":"art/story/fk-singbonga-furnaces.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.sal-grove-promise":{"id":"st-fk.sal-grove-promise","src":"story:fk.sal-grove-promise:scenes:0:text","route":"#/story/fk.sal-grove-promise","title":"The Grove the Axes Never Touch","body":"Drive through Jharkhand and you will see it again and again: open fields, houses, roads — and then, beside a village, a patch of tall old forest standing untouched, dark green and quiet, like a piece of the original world.","art":"art/story/fk-sal-grove-promise.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.karam-brothers":{"id":"st-fk.karam-brothers","src":"story:fk.karam-brothers:scenes:0:text","route":"#/story/fk.karam-brothers","title":"The Branch the Brothers Brought Home","body":"Every year, when the rains are ripening the rice, the villages of Jharkhand keep the festival of Karam. A branch of the karam tree is carried home with songs and drums, planted with honour in the courtyard, and danced around all night.","art":"art/story/fk-karam-brothers.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.bamboo-bonga":{"id":"st-fk.bamboo-bonga","src":"story:fk.bamboo-bonga:scenes:0:text","route":"#/story/fk.bamboo-bonga","title":"The Elephant and the Keeper of the Bamboo","body":"In the Santhal way of speaking, the living world is full of bongas — the spirits of places: a spirit of the hill, of the stream, of the old tree at the crossing. A place with a bonga is a place that is somebody, not just something.","art":"art/story/fk-bamboo-bonga.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.sarhul-flowers":{"id":"st-fk.sarhul-flowers","src":"story:fk.sarhul-flowers:scenes:0:text","route":"#/story/fk.sarhul-flowers","title":"When the Sal Trees Bloom","body":"Every spring, the sal forests of Jharkhand do something quietly spectacular: the great trees flower — small, cream-pale blossoms by the million, and a honeyed scent that drifts for miles. And when the sal blooms, the Adivasi new year has arrived.","art":"art/story/fk-sarhul-flowers.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.boita-bandana":{"id":"st-fk.boita-bandana","src":"story:fk.boita-bandana:scenes:0:text","route":"#/story/fk.boita-bandana","title":"Little Boats for the Big Sailors","body":"It is still dark on the morning of Kartika Purnima — the full moon of the holy month of Kartika — and all over Odisha, families are walking to water.","art":"art/story/fk-boita-bandana.jpg","cta":"Read the story","why":"From East & the Islands"},"st-it.konark-chariot":{"id":"st-it.konark-chariot","src":"story:it.konark-chariot:scenes:0:text","route":"#/story/it.konark-chariot","title":"The Chariot That Cannot Move and Never Stops","body":"On the shore of Odisha, near the sea, stands one of the most astonishing buildings human beings have ever made. This is itihaas — what the evidence shows — and the evidence is still standing there, carved in stone, for anyone to go and see: the Sun Temple of Konark.","art":"art/story/it-konark-chariot.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.manika-curd":{"id":"st-fk.manika-curd","src":"story:fk.manika-curd:scenes:0:text","route":"#/story/fk.manika-curd","title":"The Milkmaid and the Two Riders","body":"This is one of Odisha's best-loved kathas — a temple story of Puri, told for centuries. A king of Odisha, Purushottama Deva, was on a long march south with his whole army, towards far-off Kanchi.","art":"art/story/fk-manika-curd.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.rasagola-door":{"id":"st-fk.rasagola-door","src":"story:fk.rasagola-door:scenes:0:text","route":"#/story/fk.rasagola-door","title":"The Sweet That Opened the Door","body":"Every summer at Puri comes the Rath Yatra — the festival of chariots, when Jagannath, Lord of the Universe, with his brother Balabhadra and sister Subhadra, rides out of the great temple in enormous wooden chariots pulled by thousands of hands, and goes to stay at another temple up the road.","art":"art/story/fk-rasagola-door.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.ridley-night":{"id":"st-fk.ridley-night","src":"story:fk.ridley-night:scenes:0:text","route":"#/story/fk.ridley-night","title":"The Night the Sea Comes Ashore","body":"For most of the year, the long beaches of the Odisha coast at Gahirmatha and by the Rushikulya river mouth are just sand, wind and fishing boats. But the sea is keeping an appointment with these beaches — and on a few dark nights, usually late in winter, it arrives.","art":"art/story/fk-ridley-night.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.tapoi":{"id":"st-fk.tapoi","src":"story:fk.tapoi:scenes:0:text","route":"#/story/fk.tapoi","title":"Tapoi and the Seven Ships","body":"In the great sailing days of Odisha there lived a merchant with seven sons and, last and most loved, one daughter: Tapoi.","art":"art/story/fk-tapoi.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.lalkamal-nilkamal":{"id":"st-fk.lalkamal-nilkamal","src":"story:fk.lalkamal-nilkamal:scenes:0:text","route":"#/story/fk.lalkamal-nilkamal","title":"Lalkamal and Nilkamal","body":"Out of Thakurmar Jhuli — the Grandmother's Bag of Tales, Bengal's most beloved storybook — comes this one. A king had two queens.","art":"art/story/fk-lalkamal-nilkamal.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.gopal-pot-of-wit":{"id":"st-fk.gopal-pot-of-wit","src":"story:fk.gopal-pot-of-wit:scenes:0:text","route":"#/story/fk.gopal-pot-of-wit","title":"A Pot Full of Cleverness","body":"At the court of Raja Krishnachandra of Krishnanagar in Bengal, the sharpest tongue and the roundest belly both belonged to Gopal Bhar, the royal barber and jester — Bengal's answer to Birbal, and in Bengal, naturally, considered the original of the two.","art":"art/story/fk-gopal-pot-of-wit.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.bonbibi-dukhey":{"id":"st-fk.bonbibi-dukhey","src":"story:fk.bonbibi-dukhey:scenes:0:text","route":"#/story/fk.bonbibi-dukhey","title":"Bonbibi, Lady of the Forest","body":"At the bottom of Bengal, where the Ganga's hundred mouths meet the sea, lies the Sundarbans — the largest mangrove forest on Earth, a maze of tidal rivers and breathing mud and trees that stand in salt water, and the realm of the royal Bengal tiger.","art":"art/story/fk-bonbibi-dukhey.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.ilish-rain":{"id":"st-fk.ilish-rain","src":"story:fk.ilish-rain:scenes:0:text","route":"#/story/fk.ilish-rain","title":"The Fish That Comes With the Rain","body":"In Bengal, the monsoon does not arrive alone.","art":"art/story/fk-ilish-rain.jpg","cta":"Read the story","why":"From East & the Islands"},"st-fk.warli-chauk":{"id":"st-fk.warli-chauk","src":"story:fk.warli-chauk:scenes:0:text","route":"#/story/fk.warli-chauk","title":"The Painting Made of Rice","body":"In the green hills of Dadra and Nagar Haveli, where the Warli people have lived for longer than anyone can count, the houses are made of mud and bamboo, and the walls are the colour of the earth they stand on. And on those walls, the Warli paint.","art":"art/story/fk-warli-chauk.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.warli-tarpa":{"id":"st-fk.warli-tarpa","src":"story:fk.warli-tarpa:scenes:0:text","route":"#/story/fk.warli-tarpa","title":"Why the Dance Goes Round","body":"When the harvest is in, in the Warli villages of Dadra and Nagar Haveli, a man stands in an open place with a tarpa — a long horn made of dried gourds and bamboo, taller than the man himself. He fills his chest and begins to play, one endless winding note.","art":"art/story/fk-warli-tarpa.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.waghoba-watch":{"id":"st-fk.waghoba-watch","src":"story:fk.waghoba-watch:scenes:0:text","route":"#/story/fk.waghoba-watch","title":"The Tiger Who Keeps Watch","body":"Where the fields of a Warli or Kokna village end and the forest of Dadra and Nagar Haveli begins, there is often a small shrine — a carved wooden post, or a painted stone, with a tiger on it. His name is Waghoba, and the first thing to understand is that he is not the enemy.","art":"art/story/fk-waghoba-watch.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.kansari-grain":{"id":"st-fk.kansari-grain","src":"story:fk.kansari-grain:scenes:0:text","route":"#/story/fk.kansari-grain","title":"Kansari and the Last Handful","body":"In the Warli and Dhodia villages of Dadra and Nagar Haveli, the rice is not just food. Inside the grain lives Kansari — the grain mother, the one who feeds everybody. Which means a pot of rice is never only a pot of rice. It is a house with somebody in it.","art":"art/story/fk-kansari-grain.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.damanganga-winds":{"id":"st-fk.damanganga-winds","src":"story:fk.damanganga-winds:scenes:0:text","route":"#/story/fk.damanganga-winds","title":"The River That Would Not Hurry","body":"The Daman Ganga is born in the hills to the east, and she is bound for the sea at Daman — everyone knows that, even the river. What puzzles children is the map. The sea is not far.","art":"art/story/fk-damanganga-winds.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.kokna-honey":{"id":"st-fk.kokna-honey","src":"story:fk.kokna-honey:scenes:0:text","route":"#/story/fk.kokna-honey","title":"Half for the Bees","body":"The Kokna people of Dadra and Nagar Haveli have always known the forest the way you know your own kitchen — which tree gives what, and when, and how much. And of everything the forest gives, the sweetest is honey, hanging in great combs high in the old trees.","art":"art/story/fk-kokna-honey.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.dhodia-road":{"id":"st-fk.dhodia-road","src":"story:fk.dhodia-road:scenes:0:text","route":"#/story/fk.dhodia-road","title":"The Road the Grandmothers Remember","body":"The Dhodia people live today across Dadra and Nagar Haveli and the country round it — farmers, mostly, settled and rooted.","art":"art/story/fk-dhodia-road.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.hirwa-green":{"id":"st-fk.hirwa-green","src":"story:fk.hirwa-green:scenes:0:text","route":"#/story/fk.hirwa-green","title":"Hirwa of the Green","body":"By the end of May, in the hills of Dadra and Nagar Haveli, everything is brown. The fields are cut stubble, the streams are stones, the big trees stand dusty, and the heat lies on the land like a sleeping buffalo. It is hard, in May, to believe in green at all.","art":"art/story/fk-hirwa-green.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.diu-hokka":{"id":"st-fk.diu-hokka","src":"story:fk.diu-hokka:scenes:0:text","route":"#/story/fk.diu-hokka","title":"The Trees That Crossed the Sea","body":"Walk around the little island of Diu and sooner or later you will stop and stare at a tree. It is enormously fat — the trunk like a grey water-tank — with stubby branches on top, as if somebody had pulled it up and planted it upside down. In Diu they call it the hokka tree.","art":"art/story/fk-diu-hokka.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.daman-lighthouse":{"id":"st-fk.daman-lighthouse","src":"story:fk.daman-lighthouse:scenes:0:text","route":"#/story/fk.daman-lighthouse","title":"The Keeper of the Small Light","body":"Where the Daman Ganga meets the sea, the old fort of Nani Daman stands over the fishing harbour, and above its wall rises a lighthouse. This is a tale told about a keeper of that light, in the years when Daman was a Portuguese town and the lamp burned oil, not electricity.","art":"art/story/fk-daman-lighthouse.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.nagoa-shankh":{"id":"st-fk.nagoa-shankh","src":"story:fk.nagoa-shankh:scenes:0:text","route":"#/story/fk.nagoa-shankh","title":"The Shell That Called the Boats","body":"The bay at Nagoa, on the island of Diu, curves like a moon, and the fishing families have worked it for as long as anyone's grandmother's grandmother could say. The sea gives fish, and shells — and once in a long while, it gives a great conch, a shankh, big as a baby's head.","art":"art/story/fk-nagoa-shankh.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.diu-fort-cat":{"id":"st-fk.diu-fort-cat","src":"story:fk.diu-fort-cat:scenes:0:text","route":"#/story/fk.diu-fort-cat","title":"The Cat of the Sea Fort","body":"The sea fort of Diu is nearly five hundred years old — built in the days of the Portuguese, with walls like cliffs, a moat cut from rock, and old cannons still lying about like sleeping crocodiles. Ships once feared it. Schoolchildren now picnic in it. And a cat runs it.","art":"art/story/fk-diu-fort-cat.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.gangeshwar-tide":{"id":"st-fk.gangeshwar-tide","src":"story:fk.gangeshwar-tide:scenes:0:text","route":"#/story/fk.gangeshwar-tide","title":"The Shrine the Sea Visits","body":"On the rocky shore of Diu, down among the tide pools where the land gives way to the sea, there is a small shrine called Gangeshwar. It has no tall tower and no great hall. It has five shivlings, set low in the rock — and it has the ocean for a priest.","art":"art/story/fk-gangeshwar-tide.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.koli-stars":{"id":"st-fk.koli-stars","src":"story:fk.koli-stars:scenes:0:text","route":"#/story/fk.koli-stars","title":"The Fisherman's Compass","body":"The fisher families of Daman — Koli and Machhi people, whose boats have worked this coast for generations past counting — put to sea long before anyone aboard owned an instrument. This is a tale in their manner, about a girl, her grandfather, and a very shiny compass.","art":"art/story/fk-koli-stars.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.narali-punam":{"id":"st-fk.narali-punam","src":"story:fk.narali-punam:scenes:0:text","route":"#/story/fk.narali-punam","title":"The Coconut for the Sea","body":"All through the monsoon, the fishing boats of Daman stay in. The sea off this coast in the rains is no place for anyone, and the fisher families — Koli and Machhi people who know it best — do not argue with it. They mend nets, paint hulls, and wait for a particular full moon.","art":"art/story/fk-narali-punam.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.moti-daman-bells":{"id":"st-fk.moti-daman-bells","src":"story:fk.moti-daman-bells:scenes:0:text","route":"#/story/fk.moti-daman-bells","title":"The Bell That Answered Ships","body":"On the south bank of the Daman Ganga stands Moti Daman — the big fort, with walls you can walk along and a whole old town tucked inside. And inside the walls stands the Church of Bom Jesus, centuries old, with carved doors, a golden altar, and a bell up in its tower.","art":"art/story/fk-moti-daman-bells.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.goa-two-bells":{"id":"st-fk.goa-two-bells","src":"story:fk.goa-two-bells:scenes:0:text","route":"#/story/fk.goa-two-bells","title":"The Two Bells of the Valley","body":"There is a kind of Goan village — you will find it in every taluka — that sits in a green valley of coconut and rice, with a whitewashed church shining on one hill and a temple with a deepastambha, a lamp tower, on the other. This is a tale told about one such village.","art":"art/story/fk-goa-two-bells.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.goa-coconut":{"id":"st-fk.goa-coconut","src":"story:fk.goa-coconut:scenes:0:text","route":"#/story/fk.goa-coconut","title":"The Tree That Held the Village","body":"In Konkani the coconut palm is the maad, and in the old Goan reckoning a family that owned maad trees was never truly poor, whatever else went wrong. This tale, told along the Goan coast, is about the year everything else went wrong.","art":"art/story/fk-goa-coconut.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.goa-frog-rain":{"id":"st-fk.goa-frog-rain","src":"story:fk.goa-frog-rain:scenes:0:text","route":"#/story/fk.goa-frog-rain","title":"The Frog Who Called the Rain","body":"In the rice country of Goa, the farmers will tell you the frogs know the monsoon before anyone. When the paddies begin to shout with frog-song, the rain is coming — the frogs are the heralds, singing it in. This is a tale about the year the heralds nearly gave up.","art":"art/story/fk-goa-frog-rain.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.goa-shigmo":{"id":"st-fk.goa-shigmo","src":"story:fk.goa-shigmo:scenes:0:text","route":"#/story/fk.goa-shigmo","title":"When Spring Beats the Drum","body":"Every year, as winter loosens and the mango trees flower, Goa's Hindu villages begin tuning their drums. Shigmo is coming — the great spring festival of the Konkan, Goa's own cousin of Holi, and for days on end the state belongs to the drummers and the dancers.","art":"art/story/fk-goa-shigmo.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.mandovi-mugger":{"id":"st-fk.mandovi-mugger","src":"story:fk.mandovi-mugger:scenes:0:text","route":"#/story/fk.mandovi-mugger","title":"The Crocodile Who Owns His Stretch","body":"Between Goa's two great rivers, the Mandovi and the Zuari, winds a tidal channel through the mangroves — and in its warm green water live muggers: real, wild marsh crocodiles, dozing on the mud banks with the patience of logs.","art":"art/story/fk-mandovi-mugger.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.goa-mando":{"id":"st-fk.goa-mando","src":"story:fk.goa-mando:scenes:0:text","route":"#/story/fk.goa-mando","title":"The Song That Keeps the Story","body":"In the Catholic households of Goa there is a kind of song called the mando — slow, graceful, sung in Konkani, with everyone joining the refrain. It is not stage music, though it has reached stages. Its true home is a family gathered in a hall, at a wedding, in the evening.","art":"art/story/fk-goa-mando.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-fk.kharvi-wave":{"id":"st-fk.kharvi-wave","src":"story:fk.kharvi-wave:scenes:0:text","route":"#/story/fk.kharvi-wave","title":"The Sea Speaks in Sevens","body":"The Kharvi are Goa's fisher people — the ones whose canoes and nets have worked this surf since long before anyone wrote anything down about Goa at all. This is a tale in their manner, about the oldest skill on the beach: listening to the sea before you argue with it.","art":"art/story/fk-kharvi-wave.jpg","cta":"Read the story","why":"From The Coast and the Forest"},"st-it.jijabai-stories":{"id":"st-it.jijabai-stories","src":"story:it.jijabai-stories:scenes:0:text","route":"#/story/it.jijabai-stories","title":"The Stories His Mother Told","body":"Shivaji was born in the hill fort of Shivneri, in the Sahyadri mountains of Maharashtra — that much is solid record. And the person at the centre of his childhood, every account agrees, was his mother: Jijabai.","art":"art/story/it-jijabai-stories.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.warkari-ant":{"id":"st-fk.warkari-ant","src":"story:fk.warkari-ant:scenes:0:text","route":"#/story/fk.warkari-ant","title":"The Ant on the Palkhi Road","body":"Every year, in the rain month of Ashadh, the roads of Maharashtra fill with walkers — the Warkaris, lakhs upon lakhs of them, walking for days behind the palkhis of the saints to reach Vitthal, the dark god who stands waiting on his brick in Pandharpur. They sing the whole way.","art":"art/story/fk-warkari-ant.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.tukaram-notebooks":{"id":"st-fk.tukaram-notebooks","src":"story:fk.tukaram-notebooks:scenes:0:text","route":"#/story/fk.tukaram-notebooks","title":"The Notebooks That Came Back","body":"Four hundred years ago, in the village of Dehu on the Indrayani river near Pune, lived a shopkeeper-farmer named Tukaram — and out of him poured poems. Abhangs, they are called: short, blazing verses to Vitthal, in plain Marathi, the language of the kitchen and the field.","art":"art/story/fk-tukaram-notebooks.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.hirkani-cliff":{"id":"st-fk.hirkani-cliff","src":"story:fk.hirkani-cliff:scenes:0:text","route":"#/story/fk.hirkani-cliff","title":"Hirkani's Wall","body":"Raigad, Shivaji's great capital, stands on a mountain with its head in the clouds — walls where walls are needed, and where the cliff falls sheer, no walls at all, because none were needed. Nobody climbs Raigad's cliffs. That was the whole idea of Raigad.","art":"art/story/fk-hirkani-cliff.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.gir-maldhari":{"id":"st-fk.gir-maldhari","src":"story:fk.gir-maldhari:scenes:0:text","route":"#/story/fk.gir-maldhari","title":"The Forest With Two Kinds of Families","body":"Everywhere else on Earth, the wild lion's home is Africa. Everywhere except one dry, thorny, beautiful forest in Gujarat called Gir — the last home of the Asiatic lion. Every wild lion in Asia lives in and around this one forest. And they are not alone in it.","art":"art/story/fk-gir-maldhari.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.garba-lamp":{"id":"st-fk.garba-lamp","src":"story:fk.garba-lamp:scenes:0:text","route":"#/story/fk.garba-lamp","title":"The Lamp Inside the Pot","body":"For nine nights every autumn — Navratri — Gujarat dances. Not a stage of dancers and an audience watching: whole neighbourhoods, whole towns, everyone from toddlers to great-grandmothers, dancing in enormous circles late into the night. It may be the biggest dance on Earth.","art":"art/story/fk-garba-lamp.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.kutch-flamingo":{"id":"st-fk.kutch-flamingo","src":"story:fk.kutch-flamingo:scenes:0:text","route":"#/story/fk.kutch-flamingo","title":"The Pink City in the Salt","body":"In the far west of Gujarat lies one of the strangest landscapes in India: the Great Rann of Kutch. In the dry months it is a dazzling white nothing — salt to the horizon, flat as a table, shimmering with heat. No trees. No grass. By every ordinary measure, no life.","art":"art/story/fk-kutch-flamingo.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.narsinh-hundi":{"id":"st-fk.narsinh-hundi","src":"story:fk.narsinh-hundi:scenes:0:text","route":"#/story/fk.narsinh-hundi","title":"The Note of Trust","body":"Five hundred years and more ago, in Junagadh in Saurashtra, lived Narsinh Mehta — a bhakta of Krishna and a maker of songs so beloved that Gujarat calls him its Adi Kavi, the first poet.","art":"art/story/fk-narsinh-hundi.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.mandvi-ships":{"id":"st-fk.mandvi-ships","src":"story:fk.mandvi-ships:scenes:0:text","route":"#/story/fk.mandvi-ships","title":"The Ships Built by Hand","body":"On the bank of the Rukmavati river at Mandvi, in Kutch, stand wooden skeletons the size of buildings — the ribs of great ships, swarming with carpenters. They are dhows: ocean-going cargo ships built of timber, by hand, the way Mandvi has built them for over four hundred years.","art":"art/story/fk-mandvi-ships.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.dhola-maru":{"id":"st-fk.dhola-maru","src":"story:fk.dhola-maru:scenes:0:text","route":"#/story/fk.dhola-maru","title":"Dhola, Maru and the Wind-Swift Camel","body":"The singers of Rajasthan have a story they have sung for centuries, in the long ballad called Dhola-Maru.","art":"art/story/fk-dhola-maru.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.pabuji-camels":{"id":"st-fk.pabuji-camels","src":"story:fk.pabuji-camels:scenes:0:text","route":"#/story/fk.pabuji-camels","title":"How the Camels Came to the Desert","body":"In the villages of the Thar, when night falls, a bhopa — a singer-priest — sometimes unrolls a painted scroll as long as a house wall, lights a lamp, and begins to sing the epic of Pabuji: the folk hero of the desert, protector of herds, keeper of impossible promises.","art":"art/story/fk-pabuji-camels.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.deshnoke-mice":{"id":"st-fk.deshnoke-mice","src":"story:fk.deshnoke-mice:scenes:0:text","route":"#/story/fk.deshnoke-mice","title":"The Temple of the Small Ones","body":"In the town of Deshnoke, near Bikaner in the desert of Rajasthan, stands a temple with silver doors and marble lattices, built in honour of Karni Mata — a sainted woman of the Charan community who lived here six centuries ago, and whom her people revere as an embodiment of the Mother Goddess herself.","art":"art/story/fk-deshnoke-mice.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.chand-baori":{"id":"st-fk.chand-baori","src":"story:fk.chand-baori:scenes:0:text","route":"#/story/fk.chand-baori","title":"The Well That Goes Down Like a Mountain Upside-Down","body":"In the village of Abhaneri, in eastern Rajasthan, there is a hole in the ground that stops people mid-sentence. Chand Baori: a stepwell — a well with stairs — but of such a size that the word hardly serves. Thirteen storeys deep.","art":"art/story/fk-chand-baori.jpg","cta":"Read the story","why":"From The Western Lands"},"st-fk.gond-mahua":{"id":"st-fk.gond-mahua","src":"story:fk.gond-mahua:scenes:0:text","route":"#/story/fk.gond-mahua","title":"The Tree That Feeds Everyone","body":"Across the forest country of central India — the homeland of the Gond people, one of the largest Adivasi communities in the world — there grows a broad, generous tree called the mahua. And for the Gond and their neighbours, the mahua is not one tree among many.","art":"art/story/fk-gond-mahua.jpg","cta":"Read the story","why":"From The Heart of the Land"},"st-it.tansen-tigers":{"id":"st-it.tansen-tigers","src":"story:it.tansen-tigers:scenes:0:text","route":"#/story/it.tansen-tigers","title":"The Boy Who Spoke Tiger","body":"Four and a half centuries ago, near Gwalior in what is now Madhya Pradesh, in a village called Behat, there lived a boy named Ramtanu. The world would come to know him by another name — Tansen, the greatest singer of his age.","art":"art/story/it-tansen-tigers.jpg","cta":"Read the story","why":"From The Heart of the Land"},"st-it.teejan-pandavani":{"id":"st-it.teejan-pandavani","src":"story:it.teejan-pandavani:scenes:0:text","route":"#/story/it.teejan-pandavani","title":"The Girl Who Sang the Mahabharata","body":"Chhattisgarh has its own way with the Mahabharata, and it is like nothing else in India. It is called Pandavani — the songs of the Pandavas.","art":"art/story/it-teejan-pandavani.jpg","cta":"Read the story","why":"From The Heart of the Land"},"st-fk.ghotul-lamps":{"id":"st-fk.ghotul-lamps","src":"story:fk.ghotul-lamps:scenes:0:text","route":"#/story/fk.ghotul-lamps","title":"The Children's Own House","body":"In the forest country of Bastar, in southern Chhattisgarh, the Muria people have long kept an institution that visitors from everywhere find astonishing. In the village stands a spacious house — often the finest-kept in the village — that belongs to no family at all.","art":"art/story/fk-ghotul-lamps.jpg","cta":"Read the story","why":"From The Heart of the Land"},"st-fk.bastar-chariot":{"id":"st-fk.bastar-chariot","src":"story:fk.bastar-chariot:scenes:0:text","route":"#/story/fk.bastar-chariot","title":"The Chariot the Whole Forest Pulls","body":"In Jagdalpur, the old capital of Bastar in Chhattisgarh, they keep a Dussehra unlike any other in India — and they keep it longer than anyone keeps anything.","art":"art/story/fk-bastar-chariot.jpg","cta":"Read the story","why":"From The Heart of the Land"},"st-fk.myna-judge":{"id":"st-fk.myna-judge","src":"story:fk.myna-judge:scenes:0:text","route":"#/story/fk.myna-judge","title":"The Myna Who Judged the Quarrel","body":"In the forests of Bastar, in Chhattisgarh, lives a glossy black bird with bright yellow wattles called the hill myna — and she has one famous gift. She can repeat, perfectly, any voice she hears. Chhattisgarh loves her so well it made her the state bird.","art":"art/story/fk-myna-judge.jpg","cta":"Read the story","why":"From The Heart of the Land"},"st-fk.agaria-first-fire":{"id":"st-fk.agaria-first-fire","src":"story:fk.agaria-first-fire:scenes:0:text","route":"#/story/fk.agaria-first-fire","title":"The People of the First Furnace","body":"Across the hill country of Chhattisgarh and central India live the Agaria — a community whose very name carries fire in it, for ag is fire in their tongue as in many.","art":"art/story/fk-agaria-first-fire.jpg","cta":"Read the story","why":"From The Heart of the Land"},"st-fk.chitrakote-sings":{"id":"st-fk.chitrakote-sings","src":"story:fk.chitrakote-sings:scenes:0:text","route":"#/story/fk.chitrakote-sings","title":"The Waterfall That Sings","body":"In Bastar, in Chhattisgarh, the Indravati river comes to a horseshoe-shaped cliff and steps off it, all at once, in a curtain of falling water so wide that people call Chitrakote the widest waterfall in India — the country's own little Niagara, wearing a permanent scarf of mist.","art":"art/story/fk-chitrakote-sings.jpg","cta":"Read the story","why":"From The Heart of the Land"},"st-fk.danteshwari-bastar":{"id":"st-fk.danteshwari-bastar","src":"story:fk.danteshwari-bastar:scenes:0:text","route":"#/story/fk.danteshwari-bastar","title":"The Goddess Who Walked Behind","body":"Bastar, the great forest land of southern Chhattisgarh, has a mother: Danteshwari. Every community of the region — village and town, forest and field — honours her as the land's own goddess, and her chief temple stands at Dantewada, where two rivers meet.","art":"art/story/fk-danteshwari-bastar.jpg","cta":"Read the story","why":"From The Heart of the Land"},"st-fk.tejimola":{"id":"st-fk.tejimola","src":"story:fk.tejimola:scenes:0:text","route":"#/story/fk.tejimola","title":"Tejimola, Who Kept Becoming","body":"In Assam, on the bank of the great river, lived a merchant and his daughter Tejimola. Her mother was gone, and her father loved her the way you hold the last ember on a cold night. She sang while she worked — everyone on that bank knew her voice before they knew her face.","art":"art/story/fk-tejimola.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.bordoisila":{"id":"st-fk.bordoisila","src":"story:fk.bordoisila:scenes:0:text","route":"#/story/fk.bordoisila","title":"The Wind Who Runs Home to Her Mother","body":"At the very end of the cold season in Assam, when the mango trees are in flower, there always comes an evening when the wind gets up all at once — banging doors, rolling pots off verandas, sending everyone running for the washing.","art":"art/story/fk-bordoisila.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.xorai-elephant":{"id":"st-fk.xorai-elephant","src":"story:fk.xorai-elephant:scenes:0:text","route":"#/story/fk.xorai-elephant","title":"The Sparrow, the Frog, and the Very Big Elephant","body":"In an Assamese forest, in a simolu tree — the silk-cotton, the one that flowers red before it leafs — a pair of sparrows built a nest, and there were eggs in it, and the two of them took turns keeping the eggs warm and telling each other how clever they had been about the location.","art":"art/story/fk-xorai-elephant.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.burhi-aair-sadhu":{"id":"st-fk.burhi-aair-sadhu","src":"story:fk.burhi-aair-sadhu:scenes:0:text","route":"#/story/fk.burhi-aair-sadhu","title":"The Grandmother's Stories, Written Down","body":"For as long as anybody can count, the stories of Assam lived in one place: the evening.","art":"art/story/fk-burhi-aair-sadhu.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.bihu-goru":{"id":"st-fk.bihu-goru","src":"story:fk.bihu-goru:scenes:0:text","route":"#/story/fk.bihu-goru","title":"The Morning the Cows Go First","body":"In the middle of April, when the first storms have washed the dust off the world, Assam begins its year — Bohag Bihu, the Rongali Bihu, the one made of dancing. And the very first morning of it does not belong to the people at all.","art":"art/story/fk-bihu-goru.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.ali-aye-ligang":{"id":"st-fk.ali-aye-ligang","src":"story:fk.ali-aye-ligang:scenes:0:text","route":"#/story/fk.ali-aye-ligang","title":"The Day the Sowing Begins","body":"Along the Brahmaputra live the Mising people — river people, whose houses stand on stilts, the chang ghar, with the flood water allowed to pass underneath like a guest using the corridor.","art":"art/story/fk-ali-aye-ligang.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.bwisagu":{"id":"st-fk.bwisagu","src":"story:fk.bwisagu:scenes:0:text","route":"#/story/fk.bwisagu","title":"Bwisagu and the Butterfly Dance","body":"Assam is not one people, and mid-April proves it beautifully.","art":"art/story/fk-bwisagu.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.sohpetbneng":{"id":"st-fk.sohpetbneng","src":"story:fk.sohpetbneng:scenes:0:text","route":"#/story/fk.sohpetbneng","title":"The Navel of the Sky","body":"In the Khasi hills of Meghalaya there is a hill called U Lum Sohpetbneng. Take the name apart the way a Khasi grandmother would: lum is hill, sohpet is navel, bneng is the sky.","art":"art/story/fk-sohpetbneng.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.diengiei":{"id":"st-fk.diengiei","src":"story:fk.diengiei:scenes:0:text","route":"#/story/fk.diengiei","title":"The Tree That Shaded the Whole World","body":"After the seven families had settled the earth, the Khasi telling says, a tree began to grow in the west. U Diengiei, it was called. It did not stop growing.","art":"art/story/fk-diengiei.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.klew-peacock":{"id":"st-fk.klew-peacock","src":"story:fk.klew-peacock:scenes:0:text","route":"#/story/fk.klew-peacock","title":"Why the Peacock's Tail Is Full of Eyes","body":"In the Khasi telling, the sun is Ka Sngi — Ka, because she is a she; in Khasi, every name carries a U for a he or a Ka for a she, so you always know who you are talking about.","art":"art/story/fk-klew-peacock.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.ksew-market":{"id":"st-fk.ksew-market","src":"story:fk.ksew-market:scenes:0:text","route":"#/story/fk.ksew-market","title":"Why the Dog Sniffs Everybody","body":"Long ago in the Khasi hills, the telling goes, the animals held a great iew — a market, for market days are the heartbeat of these hills — and every animal kept a stall. The deer sold greens. The monkey sold fruit. Everyone sold something, and everyone came.","art":"art/story/fk-ksew-market.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.root-bridges":{"id":"st-fk.root-bridges","src":"story:fk.root-bridges:scenes:0:text","route":"#/story/fk.root-bridges","title":"The Bridge That Is Alive","body":"The southern slopes of Meghalaya, around Sohra, are the rainiest inhabited place on earth. It does not rain there the way it rains where you live. The rivers rise like something waking up, and they can take a bridge the way you take a biscuit.","art":"art/story/fk-root-bridges.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.wangala":{"id":"st-fk.wangala","src":"story:fk.wangala:scenes:0:text","route":"#/story/fk.wangala","title":"A Hundred Drums Say Thank You","body":"The western half of Meghalaya belongs to the Garo people — who call themselves A·chik, the people of the hills.","art":"art/story/fk-wangala.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.behdienkhlam":{"id":"st-fk.behdienkhlam","src":"story:fk.behdienkhlam:scenes:0:text","route":"#/story/fk.behdienkhlam","title":"Chasing the Sickness Out of Town","body":"East of the Khasi hills live the Pnar — the Jaintia people, with their own speech and their own ways, and it is worth saying clearly: Khasi and Pnar are kin, not copies. Their great festival belongs to the town of Jowai, to the monsoon, and to a very old enemy.","art":"art/story/fk-behdienkhlam.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.chemtatrawta":{"id":"st-fk.chemtatrawta","src":"story:fk.chemtatrawta:scenes:0:text","route":"#/story/fk.chemtatrawta","title":"It All Started With a Lobster","body":"In Mizoram, when everything has gone wrong at once and nobody can say whose fault it is, somebody old will sigh and say: this is the lobster all over again. And this is the story they mean.","art":"art/story/fk-chemtatrawta.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.chhura-door":{"id":"st-fk.chhura-door","src":"story:fk.chhura-door:scenes:0:text","route":"#/story/fk.chhura-door","title":"Chhura Minds the Door","body":"Mizoram's best-loved man never existed, or existed everywhere, which comes to the same thing. His name is Chhura — Chhurbura, in full — and he is a fool. Not a wicked fool, not a sad one: a magnificent one.","art":"art/story/fk-chhura-door.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.chhura-nahaia":{"id":"st-fk.chhura-nahaia","src":"story:fk.chhura-nahaia:scenes:0:text","route":"#/story/fk.chhura-nahaia","title":"The Field That Hummed","body":"Chhura had a brother called Nahaia, and Nahaia was the other kind of famous: clever. Too clever, by about ten per cent, which is the most dangerous amount. Where Chhura took your words somewhere strange, Nahaia took your things somewhere his.","art":"art/story/fk-chhura-nahaia.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.ngaitei":{"id":"st-fk.ngaitei","src":"story:fk.ngaitei:scenes:0:text","route":"#/story/fk.ngaitei","title":"Ngaitei and the River","body":"In a village above a deep green river lived a girl called Ngaitei, with her grandmother — her pi, as Mizo children say. Her father had been lost to that river long before she could remember him. Her pi's one rule was simple: fill your pot at the edge, and come straight up.","art":"art/story/fk-ngaitei.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.mauruangi":{"id":"st-fk.mauruangi","src":"story:fk.mauruangi:scenes:0:text","route":"#/story/fk.mauruangi","title":"Mauruangi and the Silk-Cotton Tree","body":"Mauruangi's mother was gone. How, the old Mizo tellings say harshly, and tonight we will say only that she was gone, and that the river had her.","art":"art/story/fk-mauruangi.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.sichangneii":{"id":"st-fk.sichangneii","src":"story:fk.sichangneii:scenes:0:text","route":"#/story/fk.sichangneii","title":"The Winged One","body":"The Mizo tellings speak of Sichangneii — winged and shining, a daughter of the sky country. Some say sky-maiden, some say bird-woman; the tellings are old enough to disagree.","art":"art/story/fk-sichangneii.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.liandova":{"id":"st-fk.liandova","src":"story:fk.liandova:scenes:0:text","route":"#/story/fk.liandova","title":"The Two Brothers and the Great Snake","body":"Liandova and his little brother Tuaisiala were orphans, and in the old hill villages an orphan's life was a cold seat by somebody else's fire.","art":"art/story/fk-liandova.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.chapchar-kut":{"id":"st-fk.chapchar-kut","src":"story:fk.chapchar-kut:scenes:0:text","route":"#/story/fk.chapchar-kut","title":"The Festival of the Waiting","body":"The farming year in the Mizo hills begins with an enormous effort: a patch of bamboo forest is cut for the year's lo, the hill field. And then — nothing. The cut bamboo must lie and dry before the clearing can be burned and sown. That drying pause is called chapchar.","art":"art/story/fk-chapchar-kut.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.unakoti":{"id":"st-fk.unakoti","src":"story:fk.unakoti:scenes:0:text","route":"#/story/fk.unakoti","title":"One Less Than a Crore","body":"In the forested north of Tripura there is a hillside that stops people mid-sentence.","art":"art/story/fk-unakoti.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.twipra-name":{"id":"st-fk.twipra-name","src":"story:fk.twipra-name:scenes:0:text","route":"#/story/fk.twipra-name","title":"The Land Beside the Water","body":"A girl in Agartala had a cousin abroad who asked her, over a crackling phone line, a simple question: what does Tripura actually mean? And she realised she did not know. So she did the correct thing, which was to ask a grandparent.","art":"art/story/fk-twipra-name.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.kharchi-fourteen":{"id":"st-fk.kharchi-fourteen","src":"story:fk.kharchi-fourteen:scenes:0:text","route":"#/story/fk.kharchi-fourteen","title":"The Week of the Fourteen Gods","body":"In Old Agartala, a little way out of Tripura's capital, stands a temple that holds something found nowhere else: the Chaturdasha Devata, the Fourteen Gods of Tripura, kept together as one family of the divine — the special guardians of the land since the days of its kings.","art":"art/story/fk-kharchi-fourteen.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.garia-puja":{"id":"st-fk.garia-puja","src":"story:fk.garia-puja:scenes:0:text","route":"#/story/fk.garia-puja","title":"The God Who Comes Up Your Steps","body":"When the new year turns in the hills of Tripura — mid-April, the same great turning the whole valley-and-hill world shares — the Tripuri, Jamatia and Reang communities keep the days of Garia, and Garia is not a god you go to. Garia comes to you.","art":"art/story/fk-garia-puja.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.rignai-loom":{"id":"st-fk.rignai-loom","src":"story:fk.rignai-loom:scenes:0:text","route":"#/story/fk.rignai-loom","title":"The Loom Tied to the Weaver","body":"On verandas all over the hills of Tripura you will find a loom with no frame, no legs, and no machine anywhere in it. One end of the threads is tied to the wall or a post. The other end is a strap — and the strap goes around the weaver's own back.","art":"art/story/fk-rignai-loom.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.matabari-turtles":{"id":"st-fk.matabari-turtles","src":"story:fk.matabari-turtles:scenes:0:text","route":"#/story/fk.matabari-turtles","title":"The Mother's House by the Turtle Lake","body":"In Udaipur, in the green south of Tripura, stands the state's most beloved temple: Tripura Sundari, the beautiful goddess of the land.","art":"art/story/fk-matabari-turtles.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.bizhu":{"id":"st-fk.bizhu","src":"story:fk.bizhu:scenes:0:text","route":"#/story/fk.bizhu","title":"Flowers on the Water at Dawn","body":"Among the peoples of Tripura are the Chakma — a community spread across Tripura, Mizoram and beyond, with their own language, their own script, and their Buddhist faith carried through every move their history forced on them.","art":"art/story/fk-bizhu.jpg","cta":"Read the story","why":"From The Eastern Hills"},"st-fk.sandrembi":{"id":"st-fk.sandrembi","src":"story:fk.sandrembi:scenes:0:text","route":"#/story/fk.sandrembi","title":"Sandrembi and the Grey Dove","body":"In a Meitei village in Manipur lived two girls under one roof: Sandrembi, and her stepsister Chaisra. It was the sort of house where one girl got the new phanek — the wrap that Meitei women wear — and the other girl got the mending. Sandrembi got the mending.","art":"art/story/fk-sandrembi.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.khamba-thoibi":{"id":"st-fk.khamba-thoibi","src":"story:fk.khamba-thoibi:scenes:0:text","route":"#/story/fk.khamba-thoibi","title":"Khamba, Thoibi and the Great Bull","body":"On the shore of the great Loktak lake stands Moirang, which in the old days was a kingdom of its own, with its own god — Thangjing — and its own singers. The singers play the pena, a little fiddle with a voice like a mosquito and a memory a thousand years long.","art":"art/story/fk-khamba-thoibi.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.loktak-ima":{"id":"st-fk.loktak-ima","src":"story:fk.loktak-ima:scenes:0:text","route":"#/story/fk.loktak-ima","title":"The Lake That Holds Everything Up","body":"From the hills, Loktak looks like a piece of sky that fell into the valley and decided to stay. It is the biggest lake in the Northeast, and it is scattered all over with rings and cushions of green — phumdi, the Meitei word for them. Floating meadows.","art":"art/story/fk-loktak-ima.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.sagol-kangjei":{"id":"st-fk.sagol-kangjei","src":"story:fk.sagol-kangjei:scenes:0:text","route":"#/story/fk.sagol-kangjei","title":"The Game That Rode Out of Manipur","body":"In the middle of Imphal there is a grass field that people call the oldest polo ground in the world. Mapal Kangjeibung, it is named. And the game played on it is older than anybody's counting: sagol kangjei — sagol for the pony, kangjei for the stick.","art":"art/story/fk-sagol-kangjei.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.tapta":{"id":"st-fk.tapta","src":"story:fk.tapta:scenes:0:text","route":"#/story/fk.tapta","title":"Tapta","body":"On the edge of a Meitei village lived an old woman in a hut with a thatch roof, and the thatch had seen better years. One night it rained the way it rains in Manipur — which is to say, as though the sky had decided to move in.","art":"art/story/fk-tapta.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.phunga-wari":{"id":"st-fk.phunga-wari","src":"story:fk.phunga-wari:scenes:0:text","route":"#/story/fk.phunga-wari","title":"The Fire Where the Stories Live","body":"In a Meitei house the kitchen fire has a name of its own: the phunga. And the stories told around it have a name of their own too — phunga wari, which means, exactly, hearthside tales. Pebet is one. Sandrembi is one. Tapta is one. They all live at the fire.","art":"art/story/fk-phunga-wari.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.lai-haraoba":{"id":"st-fk.lai-haraoba","src":"story:fk.lai-haraoba:scenes:0:text","route":"#/story/fk.lai-haraoba","title":"The Dance That Remembers the Making","body":"Every year, when the season comes, a Meitei neighbourhood holds Lai Haraoba at the shrine of its own old god — one of the umang lai, the deities of the sacred groves. The name means the merrymaking of the gods. Not the fearing. The merrymaking.","art":"art/story/fk-lai-haraoba.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.ao-six-stones":{"id":"st-fk.ao-six-stones","src":"story:fk.ao-six-stones:scenes:0:text","route":"#/story/fk.ao-six-stones","title":"The Six Stones and the River","body":"Ask an Ao elder in Nagaland where the Ao people began, and you will not get a vague answer. You will get a place. Chungliyimti, on its ridge above the Dikhu river — and at Chungliyimti, six stones. Longterok, the Ao call them: the six stones.","art":"art/story/fk-ao-six-stones.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.makhel-pear":{"id":"st-fk.makhel-pear","src":"story:fk.makhel-pear:scenes:0:text","route":"#/story/fk.makhel-pear","title":"The Tree Where Everyone Said Goodbye","body":"The Angami of Nagaland — and their kin, the Chakhesang, the Mao, the Poumai and others, who together call themselves Tenyimia — tell of a village where, long ago, all of them lived as one people. Makhel, it is called.","art":"art/story/fk-makhel-pear.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.naga-rooster-sun":{"id":"st-fk.naga-rooster-sun","src":"story:fk.naga-rooster-sun:scenes:0:text","route":"#/story/fk.naga-rooster-sun","title":"The Rooster Who Keeps the Sun's Appointment","body":"In the Angami country around Kohima they tell that once, long ago, the sun lost her timekeeping. Nobody had ever told her when morning was — she had always guessed. And one season, tired and huffy after some slight the tellings disagree about, she stopped guessing. She rose late.","art":"art/story/fk-naga-rooster-sun.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.hornbill-honour":{"id":"st-fk.hornbill-honour","src":"story:fk.hornbill-honour:scenes:0:text","route":"#/story/fk.hornbill-honour","title":"Why the Hornbill Feather Is Earned","body":"In the old dress of the Naga hills, a feather was not decoration. A hornbill feather, black and white and banded like a signature, was worn in the headdress — and not by whoever wanted one. It was earned, and everyone in the village knew exactly who had earned it and how.","art":"art/story/fk-hornbill-honour.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.hornbill-kisama":{"id":"st-fk.hornbill-kisama","src":"story:fk.hornbill-kisama:scenes:0:text","route":"#/story/fk.hornbill-kisama","title":"The Festival of Festivals","body":"Nagaland is not one people. It is many — Ao, Angami, Sumi, Lotha, Konyak, Chakhesang, Rengma, and more — each with its own language, its own weave, its own festivals, its own way of building a house.","art":"art/story/fk-hornbill-kisama.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.cat-tiger-lesson":{"id":"st-fk.cat-tiger-lesson","src":"story:fk.cat-tiger-lesson:scenes:0:text","route":"#/story/fk.cat-tiger-lesson","title":"The Lesson the Cat Kept Back","body":"In the Naga hills they tell that the tiger was not born knowing how to be a tiger. Once, long ago, he was just big — big and clumsy, all thump and crash, going hungry in a forest full of dinner.","art":"art/story/fk-cat-tiger-lesson.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.sungkong-drum":{"id":"st-fk.sungkong-drum","src":"story:fk.sungkong-drum:scenes:0:text","route":"#/story/fk.sungkong-drum","title":"The Drum the Whole Village Pulled","body":"In an Ao village in Nagaland, the biggest voice does not belong to any person. It belongs to the sungkong — the log drum.","art":"art/story/fk-sungkong-drum.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.bomong-bong":{"id":"st-fk.bomong-bong","src":"story:fk.bomong-bong:scenes:0:text","route":"#/story/fk.bomong-bong","title":"The Two Sun Sisters","body":"The Adi people of Arunachal Pradesh tell that in the beginning the sky was held up by two sisters, daughters of the Earth and the Sky themselves: Bomong and Bong. Both of them shone. Both of them were suns.","art":"art/story/fk-bomong-bong.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.donyi-polo":{"id":"st-fk.donyi-polo","src":"story:fk.donyi-polo:scenes:0:text","route":"#/story/fk.donyi-polo","title":"The Eye of the Day, the Eye of the Night","body":"In a Galo village in Arunachal Pradesh, a boy noticed a thing his grandfather did. Whenever the old man gave his word on something that mattered — a field boundary, a promise to a neighbour — he would lift his chin, just slightly, toward the sun. Everyone seemed to understand it.","art":"art/story/fk-donyi-polo.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.kine-nane":{"id":"st-fk.kine-nane","src":"story:fk.kine-nane:scenes:0:text","route":"#/story/fk.kine-nane","title":"The Mother of the Grain","body":"The Adi of Arunachal Pradesh remember a time before rice. People ate what the forest offered — wild yams, shoots, whatever the day turned up — and the forest is generous, but not reliable. Some weeks were full. Some weeks were an ache.","art":"art/story/fk-kine-nane.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.nyokum":{"id":"st-fk.nyokum","src":"story:fk.nyokum:scenes:0:text","route":"#/story/fk.nyokum","title":"The Festival Where Everyone Is Invited","body":"The Nyishi are the largest of the peoples of Arunachal Pradesh, and every year, as winter loosens, they keep Nyokum. The name says what it is: nyok is the land, and Nyokum is the goddess of the land and its plenty — the one whose festival this is.","art":"art/story/fk-nyokum.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.abotani-taki":{"id":"st-fk.abotani-taki","src":"story:fk.abotani-taki:scenes:0:text","route":"#/story/fk.abotani-taki","title":"Abo Tani and the Roasted Seed","body":"Abo Tani, the first man, the ancestor of the Tani peoples of Arunachal, spent half his life in contests of wits with the spirits — winning some, losing some, and turning even the losses into lessons his children still use. The Nyishi and Galo tell whole evenings of these.","art":"art/story/fk-abotani-taki.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.abotani-sky-bride":{"id":"st-fk.abotani-sky-bride","src":"story:fk.abotani-sky-bride:scenes:0:text","route":"#/story/fk.abotani-sky-bride","title":"How Abo Tani Married the Sky","body":"In many tellings of the Tani peoples, Abo Tani — the first man — did not marry just anyone. He set his heart on a daughter of the sky's own household, of the house of Donyi, the sun. Which meant asking.","art":"art/story/fk-abotani-sky-bride.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.tawang-horse":{"id":"st-fk.tawang-horse","src":"story:fk.tawang-horse:scenes:0:text","route":"#/story/fk.tawang-horse","title":"The Horse Who Chose the Monastery","body":"In the far west of Arunachal Pradesh, up where the air is thin and the prayer flags never stop moving, live the Monpa people, who follow the Buddha's path. And above their valleys stands one of the largest monasteries in all the Himalaya — Tawang.","art":"art/story/fk-tawang-horse.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.teesta-rangeet":{"id":"st-fk.teesta-rangeet","src":"story:fk.teesta-rangeet:scenes:0:text","route":"#/story/fk.teesta-rangeet","title":"The Race of the Two Rivers","body":"The Lepcha of Sikkim tell that their two great rivers were once two who loved each other: Rongnyu, whom the maps now call the Teesta, and Rongeet, who keeps his name.","art":"art/story/fk-teesta-rangeet.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.tendong-hill":{"id":"st-fk.tendong-hill","src":"story:fk.tendong-hill:scenes:0:text","route":"#/story/fk.tendong-hill","title":"The Hill That Held Its People Up","body":"The Lepcha of Sikkim tell of a time, deep in the long-ago, when the rains would not stop. Some tellings say it began with the quarrel of the two rivers; some do not say why at all, because rain does not always give reasons. The valleys filled. The rivers forgot their banks.","art":"art/story/fk-tendong-hill.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.khangchendzonga-five":{"id":"st-fk.khangchendzonga-five","src":"story:fk.khangchendzonga-five:scenes:0:text","route":"#/story/fk.khangchendzonga-five","title":"The Five Treasures of the Great Snow","body":"Over Sikkim stands Khangchendzonga, the third-highest mountain in the world — and to the Bhutia and the Lepcha, far more than that. Say its name slowly, the way the Bhutia gave it: Khang-chen-dzö-nga. The great snow of the five treasuries. The name is not a description.","art":"art/story/fk-khangchendzonga-five.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.kabi-lungchok":{"id":"st-fk.kabi-lungchok","src":"story:fk.kabi-lungchok:scenes:0:text","route":"#/story/fk.kabi-lungchok","title":"The Brothers of the Standing Stones","body":"Long ago in Sikkim, two peoples found themselves sharing one small, steep, beautiful country. The Lepcha had been there since before memory — the children of the snowy peak. The Bhutia had come over the high passes from the north with their yaks and their prayer flags.","art":"art/story/fk-kabi-lungchok.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.mutanchi":{"id":"st-fk.mutanchi","src":"story:fk.mutanchi:scenes:0:text","route":"#/story/fk.mutanchi","title":"The Children of the Snowy Peak","body":"Every people carries an answer to the oldest question — where do we come from? — and the Lepcha answer of Sikkim may be the most beautiful one in these mountains. They come, their telling says, from the mountain itself.","art":"art/story/fk-mutanchi.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.snow-keeper":{"id":"st-fk.snow-keeper","src":"story:fk.snow-keeper:scenes:0:text","route":"#/story/fk.snow-keeper","title":"The Shy Keeper of the High Snows","body":"Above the last villages of Sikkim, above the yak pastures, above even the prayer flags, there is a country that belongs to nobody — the high snows. Except that the herders who summer up near it, Bhutia and Lepcha both, will quietly tell you it does belong to somebody.","art":"art/story/fk-snow-keeper.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-fk.losoong":{"id":"st-fk.losoong","src":"story:fk.losoong:scenes:0:text","route":"#/story/fk.losoong","title":"The Year Is Swept Out Dancing","body":"When the harvest is in and the high passes have gone white, Sikkim turns the year.","art":"art/story/fk-losoong.jpg","cta":"Read the story","why":"From Hills of the Dawn"},"st-kh.dhyanchand":{"id":"st-kh.dhyanchand","src":"story:kh.dhyanchand:scenes:0:text","route":"#/story/kh.dhyanchand","title":"The Wizard With the Stick","body":"This is a true story — itihaas, what the record books show. Around a hundred years ago, a young soldier named Dhyan Chand played hockey for the Indian army.","art":"art/story/kh-dhyanchand.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.kapil83":{"id":"st-kh.kapil83","src":"story:kh.kapil83:scenes:0:text","route":"#/story/kh.kapil83","title":"The Cup Nobody Expected","body":"In the summer of 1983, India went to England for the cricket World Cup, and almost nobody noticed. India had won one single match in the two World Cups before. The bookmakers offered sixty-six to one against them.","art":"art/story/kh-kapil83.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.sachin":{"id":"st-kh.sachin","src":"story:kh.sachin:scenes:0:text","route":"#/story/kh.sachin","title":"The Boy With the Ball in a Sock","body":"In a colony in Bandra, Bombay, in the 1980s, a small boy with curly hair practised batting against a cricket ball hung inside a sock from a rope — because a ball in a sock swings back at you, again and again, and never needs a bowler.","art":"art/story/kh-sachin.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.anand":{"id":"st-kh.anand","src":"story:kh.anand:scenes:0:text","route":"#/story/kh.anand","title":"The Lightning Kid","body":"Chess was born in India — its ancestor, chaturanga, was played here some fourteen centuries ago before travelling the whole world and coming home changed. But by the 1980s, the world’s great chess powers were far away, and India did not have one single grandmaster.","art":"art/story/kh-anand.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.marykom":{"id":"st-kh.marykom","src":"story:kh.marykom:scenes:0:text","route":"#/story/kh.marykom","title":"Six Crowns from Kangathei","body":"Kangathei is a small village in Manipur, in the beautiful hill country of India’s northeast, and Mary Kom grew up there helping her parents in the rice fields. In 1998, a boxer from Manipur named Dingko Singh won gold at the Asian Games, and the whole state lit up.","art":"art/story/kh-marykom.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.sindhu":{"id":"st-kh.sindhu","src":"story:kh.sindhu:scenes:0:text","route":"#/story/kh.sindhu","title":"The Girl Who Woke Before the Birds","body":"P. V. Sindhu was born in Hyderabad into a house full of sport — both her parents played volleyball for India.","art":"art/story/kh-sindhu.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.neeraj":{"id":"st-kh.neeraj","src":"story:kh.neeraj:scenes:0:text","route":"#/story/kh.neeraj","title":"The Spear From Khandra","body":"Khandra is a farming village near Panipat, in Haryana — wheat fields, buffaloes, a big joint family in one house. Neeraj Chopra was the cheerful, roundish kid of that family, and when he was about thirteen his uncle marched him to the stadium in town to get some exercise.","art":"art/story/kh-neeraj.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.avani":{"id":"st-kh.avani","src":"story:kh.avani:scenes:0:text","route":"#/story/kh.avani","title":"The Stillest Person in the Room","body":"Avani Lekhara grew up in Jaipur, in Rajasthan. When she was eleven, a car accident injured her spine, and from then on she has used a wheelchair.","art":"art/story/kh-avani.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.gukesh":{"id":"st-kh.gukesh","src":"story:kh.gukesh:scenes:0:text","route":"#/story/kh.gukesh","title":"Eighteen, and King of the World","body":"Remember the Lightning Kid, who brought the chess crown home to Chennai? This story is what grew from that one.","art":"art/story/kh-gukesh.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.dhoni":{"id":"st-kh.dhoni","src":"story:kh.dhoni:scenes:0:text","route":"#/story/kh.dhoni","title":"The Ticket Collector Who Finished It","body":"Mahendra Singh Dhoni grew up in Ranchi — a town of forests and iron country, in what is now Jharkhand, about as far from cricket’s famous cities as an Indian boy could be.","art":"art/story/kh-dhoni.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.kohli":{"id":"st-kh.kohli","src":"story:kh.kohli:scenes:0:text","route":"#/story/kh.kohli","title":"The Boy Who Batted That Morning","body":"In the summer of 1998, a nine-year-old from West Delhi joined a brand-new cricket academy in his neighbourhood, and his father began a routine that lasted years: driving the boy to practice and back on his scooter, day after day, through Delhi’s traffic and Delhi’s weather.","art":"art/story/kh-kohli.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.mithali":{"id":"st-kh.mithali","src":"story:kh.mithali:scenes:0:text","route":"#/story/kh.mithali","title":"The Dancer at the Crease","body":"Mithali Raj grew up in Hyderabad, in an Air Force family, and for eight years her mornings belonged to bharatanatyam — the anklets, the postures held until they burned, the discipline of classical dance.","art":"art/story/kh-mithali.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.saina":{"id":"st-kh.saina","src":"story:kh.saina:scenes:0:text","route":"#/story/kh.saina","title":"The First Shuttle Through the Door","body":"Saina Nehwal was born in 1990 in Hisar, in Haryana — wrestling country, wheat country, not badminton country.","art":"art/story/kh-saina.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.malleswari":{"id":"st-kh.malleswari","src":"story:kh.malleswari:scenes:0:text","route":"#/story/kh.malleswari","title":"Iron in the Village","body":"Voosavanipeta is a village in Srikakulam district, on the Andhra coast, and in the 1980s it held something unusual: a little gymnasium with a mud floor where a local coach taught the iron game — weightlifting.","art":"art/story/kh-malleswari.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-kh.mirabai":{"id":"st-kh.mirabai","src":"story:kh.mirabai:scenes:0:text","route":"#/story/kh.mirabai","title":"The Girl Who Carried the Firewood","body":"Nongpok Kakching is a village in the hills of Manipur, a bumpy hour from Imphal, and like most village children Saikhom Mirabai Chanu grew up doing chores — among them, fetching firewood from the hillsides.","art":"art/story/kh-mirabai.jpg","cta":"Read the story","why":"From Khel — India at Play"},"st-ny.kurien":{"id":"st-ny.kurien","src":"story:ny.kurien:scenes:0:text","route":"#/story/ny.kurien","title":"The Milkman of India","body":"In 1949 a young engineer named Verghese Kurien, from Kozhikode in Kerala, was ordered by the government to a small dusty town in Gujarat called Anand, to work at a creamery. He had studied metallurgy — metals, not milk.","art":"art/story/ny-kurien.jpg","cta":"Read the story","why":"From Naya India — The Builders"},"st-ny.infosys":{"id":"st-ny.infosys","src":"story:ny.infosys:scenes:0:text","route":"#/story/ny.infosys","title":"Ten Thousand Rupees and Seven Engineers","body":"In 1981, a soft-spoken engineer named N. R. Narayana Murthy wanted to start a software company — in an India where that sentence barely made sense. Computers were rare, imports took forever, and software was something faraway countries did.","art":"art/story/ny-infosys.jpg","cta":"Read the story","why":"From Naya India — The Builders"},"st-ny.sudha-letter":{"id":"st-ny.sudha-letter","src":"story:ny.sudha-letter:scenes:0:text","route":"#/story/ny.sudha-letter","title":"The Postcard to Mr Tata","body":"In 1974, Sudha Kulkarni — later Sudha Murty — was a star engineering student in Bangalore, usually the only woman in the room and usually at the top of the class. One day on a notice board she saw an advertisement from TELCO, the great Tata company that built trucks.","art":"art/story/ny-sudha-letter.jpg","cta":"Read the story","why":"From Naya India — The Builders"},"st-ny.isro":{"id":"st-ny.isro","src":"story:ny.isro:scenes:0:text","route":"#/story/ny.isro","title":"From a Church Yard to Mars","body":"In 1963, India’s space programme fitted inside a fishing village.","art":"art/story/ny-isro.jpg","cta":"Read the story","why":"From Naya India — The Builders"},"st-ny.upi":{"id":"st-ny.upi","src":"story:ny.upi:scenes:0:text","route":"#/story/ny.upi","title":"The Square That Ate the Wallet","body":"Watch a chai stall in any Indian street today. A cup is poured, a phone comes out, it points for a second at a small printed square hanging on a string — and the payment is done.","art":"art/story/ny-upi.jpg","cta":"Read the story","why":"From Naya India — The Builders"},"st-ny.flipkart":{"id":"st-ny.flipkart","src":"story:ny.flipkart:scenes:0:text","route":"#/story/ny.flipkart","title":"Two Bansals and a Bookshop in the Air","body":"In 2007, two young engineers in Bengaluru — Sachin Bansal and Binny Bansal, same surname, no relation, a coincidence they explained for the rest of their lives — quit comfortable jobs to try something most of India found funny at the time: a shop with no shop.","art":"art/story/ny-flipkart.jpg","cta":"Read the story","why":"From Naya India — The Builders"},"st-ny.nykaa":{"id":"st-ny.nykaa","src":"story:ny.nykaa:scenes:0:text","route":"#/story/ny.nykaa","title":"The Bell She Rang at Fifty","body":"Falguni Nayar had, by any sensible measure, finished the climbing part of life. She was one of the most senior bankers in Mumbai, respected everywhere, her twin children grown.","art":"art/story/ny-nykaa.jpg","cta":"Read the story","why":"From Naya India — The Builders"},"st-ny.oyo":{"id":"st-ny.oyo","src":"story:ny.oyo:scenes:0:text","route":"#/story/ny.oyo","title":"The Teenager Who Slept in a Hundred Guest Houses","body":"Ritesh Agarwal grew up in Bissam Cuttack, a small town in Odisha, in a family of shopkeepers. As a teenager he fell in love with travelling — and, having very little money, he stayed where very little money stays: cheap guest houses.","art":"art/story/ny-oyo.jpg","cta":"Read the story","why":"From Naya India — The Builders"},"st-rah.kiran":{"id":"st-rah.kiran","src":"story:rah.kiran:scenes:0:text","route":"#/story/rah.kiran","title":"The Brewmaster Nobody Would Hire","body":"Kiran Mazumdar grew up in Bangalore in the 1950s and 60s, the daughter of a head brewmaster — and she fell in love not with beer but with the science underneath it: fermentation, the ancient trick by which invisible living things, yeasts and enzymes, quietly turn one substance into another.","art":"art/story/rah-kiran.jpg","cta":"Read the story","why":"From Rah Banane Wale — The Pathbreakers"},"st-rah.hansa":{"id":"st-rah.hansa","src":"story:rah.hansa:scenes:0:text","route":"#/story/rah.hansa","title":"All Human Beings","body":"Hansa Mehta was born in 1897 into a scholarly family of Baroda, in Gujarat, and spent her life on education — she wrote and translated books for Gujarati children, Gulliver’s adventures among them, and built schools and colleges.","art":"art/story/rah-hansa.jpg","cta":"Read the story","why":"From Rah Banane Wale — The Pathbreakers"},"st-rah.ela":{"id":"st-rah.ela","src":"story:rah.ela:scenes:0:text","route":"#/story/rah.ela","title":"A Bank of Four Thousand Sisters","body":"Ela Bhatt was a young lawyer in Ahmedabad — soft-spoken, khadi-wearing, the gentlest person in most rooms — working for the textile workers’ union in the city Gandhi had made famous for exactly that kind of work. But the workers inside the mills had a union.","art":"art/story/rah-ela.jpg","cta":"Read the story","why":"From Rah Banane Wale — The Pathbreakers"},"st-sci-aryabhata":{"id":"st-sci-aryabhata","src":"story:sci-aryabhata:scenes:0:text","route":"#/story/sci-aryabhata","title":"The Man Who Made Nothing Count","body":"In the year 499 CE, in Kusumapura — near today's Patna, in Bihar — a scholar finished a book of mathematics and astronomy written entirely in verse, so that it could be memorised and carried in people's heads.","art":"art/story/sci-aryabhata.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-jcbose":{"id":"st-sci-jcbose","src":"story:sci-jcbose:scenes:0:text","route":"#/story/sci-jcbose","title":"The Scientist Who Listened to Plants","body":"Jagadish Chandra Bose taught physics at Presidency College in Kolkata in the 1890s, in a laboratory that was barely a laboratory — a small room, almost no money for equipment.","art":"art/story/sci-jcbose.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-raman":{"id":"st-sci-raman","src":"story:sci-raman:scenes:0:text","route":"#/story/sci-raman","title":"Why Is the Sea Blue?","body":"Chandrasekhara Venkata Raman, born in Tiruchirappalli in Tamil Nadu, was sailing home from London in 1921, and the Mediterranean was outrageously blue. The books had an answer ready: the sea reflects the sky, said the great Lord Rayleigh, and everyone repeated it.","art":"art/story/sci-raman.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-ramanujan":{"id":"st-sci-ramanujan","src":"story:sci-ramanujan:scenes:0:text","route":"#/story/sci-ramanujan","title":"The Clerk Who Wrote to Cambridge","body":"Srinivasa Ramanujan, from Erode and Kumbakonam in Tamil Nadu, worked as a clerk at the Madras Port Trust, counting other people's cargo for a small salary. He had failed out of college — twice — because he would study nothing, absolutely nothing, except mathematics.","art":"art/story/sci-ramanujan.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-janaki":{"id":"st-sci-janaki","src":"story:sci-janaki:scenes:0:text","route":"#/story/sci-janaki","title":"The Woman Who Sweetened the Sugarcane","body":"Edavaleth Kakkat Janaki Ammal was born in 1897 in Thalassery, on the Kerala coast, into a big house full of children where her father kept a garden and wrote about birds.","art":"art/story/sci-janaki.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-bhabha":{"id":"st-sci-bhabha","src":"story:sci-bhabha:scenes:0:text","route":"#/story/sci-bhabha","title":"A Home for Science","body":"Homi Jehangir Bhabha, born in Bombay in 1909, was by his twenties a physicist with a growing name at Cambridge, working on cosmic rays — particles that fall on us from space. In 1939 he came home to India on holiday.","art":"art/story/sci-bhabha.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-sarabhai":{"id":"st-sci-sarabhai","src":"story:sci-sarabhai:scenes:0:text","route":"#/story/sci-sarabhai","title":"The Rocket in the Church","body":"Vikram Sarabhai was born in 1919 into a great mill-owning family of Ahmedabad, in Gujarat, and could have spent his life comfortably running factories.","art":"art/story/sci-sarabhai.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-swaminathan":{"id":"st-sci-swaminathan","src":"story:sci-swaminathan:scenes:0:text","route":"#/story/sci-swaminathan","title":"The Wheat That Would Not Fall Over","body":"Monkombu Sambasivan Swaminathan, born in Kumbakonam in Tamil Nadu in 1925, was a student in 1943 when famine struck Bengal and people died in the streets in numbers that are hard to write down.","art":"art/story/sci-swaminathan.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-salimali":{"id":"st-sci-salimali","src":"story:sci-salimali:scenes:0:text","route":"#/story/sci-salimali","title":"The Fall of a Sparrow","body":"Salim Ali grew up in Bombay around 1900, an orphan raised in a big, warm houseful of uncles and cousins, and like a lot of boys then he had an airgun and used it on sparrows. One day he picked up a sparrow he had shot and stopped. On its throat was a patch of yellow.","art":"art/story/sci-salimali.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-kalam":{"id":"st-sci-kalam","src":"story:sci-kalam:scenes:0:text","route":"#/story/sci-kalam","title":"The Newspaper Boy of Rameswaram","body":"Avul Pakir Jainulabdeen Abdul Kalam was born in 1931 in Rameswaram, the island temple-town at the very toe of Tamil Nadu, where his father owned a wooden boat that ferried pilgrims.","art":"art/story/sci-kalam.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-annamani":{"id":"st-sci-annamani","src":"story:sci-annamani:scenes:0:text","route":"#/story/sci-annamani","title":"The Girl Who Refused the Earrings","body":"Anna Mani was born in 1918 in Peermade, in the hills of Kerala, into a prosperous family with settled ideas about what girls were for. By eight she had read most of what her town could offer a child.","art":"art/story/sci-annamani.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-sci-tessy":{"id":"st-sci-tessy","src":"story:sci-tessy:scenes:0:text","route":"#/story/sci-tessy","title":"The Engineer Who Steered the Fire","body":"Tessy Thomas was born in 1963 in Alappuzha, Kerala — a town of canals and coir — and named, her family has said, after Mother Teresa.","art":"art/story/sci-tessy.jpg","cta":"Read the story","why":"From Vigyan — The Scientists"},"st-dv.what-is-an-avatar":{"id":"st-dv.what-is-an-avatar","src":"story:dv.what-is-an-avatar:scenes:0:text","route":"#/story/dv.what-is-an-avatar","title":"The Word That Means Coming Down","body":"You already know the word. When you make a little person in a game and send them into the world, you call it your avatar. That word is Sanskrit, and it is much older than any game. Avatara. It means a coming-down.","art":"art/story/dv-what-is-an-avatar.jpg","cta":"Read the story","why":"From The Ten Avatars"},"st-dv.matsya":{"id":"st-dv.matsya","src":"story:dv.matsya:scenes:0:text","route":"#/story/dv.matsya","title":"The Fish Who Kept Outgrowing the Bowl","body":"A king called Manu was standing in a river, letting the water run over his hands, when something very small swam into his palm and stayed there. A fish, no longer than his thumb.","art":"art/story/dv-matsya.jpg","cta":"Read the story","why":"From The Ten Avatars"},"st-dv.kurma":{"id":"st-dv.kurma","src":"story:dv.kurma:scenes:0:text","route":"#/story/dv.kurma","title":"The Tortoise Under the Mountain","body":"The devas had lost their strength. Somewhere at the bottom of the ocean of milk lay amrita, the nectar that ends dying — but the ocean does not simply hand things over.","art":"art/story/dv-kurma.jpg","cta":"Read the story","why":"From The Ten Avatars"},"st-dv.varaha":{"id":"st-dv.varaha","src":"story:dv.varaha:scenes:0:text","route":"#/story/dv.varaha","title":"The Boar Who Lifted the Earth","body":"Hiranyaksha was an asura of enormous strength, and he was proud of it in the way that strong people sometimes are — he wanted somewhere to put it. So he took the whole earth and carried it down under the cosmic ocean, and left it there, and dared anyone to come and take it back.","art":"art/story/dv-varaha.jpg","cta":"Read the story","why":"From The Ten Avatars"},"st-dv.narasimha":{"id":"st-dv.narasimha","src":"story:dv.narasimha:scenes:0:text","route":"#/story/dv.narasimha","title":"Not Day, Not Night, Not Inside, Not Outside","body":"Hiranyakashipu was an emperor of the asuras, and after long, long effort he was granted a boon — and he had thought about the wording very carefully indeed.","art":"art/story/dv-narasimha.jpg","cta":"Read the story","why":"From The Ten Avatars"},"st-dv.vamana":{"id":"st-dv.vamana","src":"story:dv.vamana:scenes:0:text","route":"#/story/dv.vamana","title":"Three Steps, and a King Who Kept His Word","body":"Mahabali was an asura king, and he was a good one. That is not a twist in this story; it is the starting point. Under Bali nobody lied, nobody was hungry, nobody was cheated, and nobody locked a door. His people adored him. They still do.","art":"art/story/dv-vamana.jpg","cta":"Read the story","why":"From The Ten Avatars"},"st-dv.parashurama":{"id":"st-dv.parashurama","src":"story:dv.parashurama:scenes:0:text","route":"#/story/dv.parashurama","title":"The Sage Who Carried an Axe","body":"Parashurama was born into a family of sages, and he was a scholar before he was anything else. The axe he is named for — parashu — was given to him by Shiva. That is an unusual combination, and the stories know it: a man trained to think, holding a weapon.","art":"art/story/dv-parashurama.jpg","cta":"Read the story","why":"From The Ten Avatars"},"st-dv.rama":{"id":"st-dv.rama","src":"story:dv.rama:scenes:0:text","route":"#/story/dv.rama","title":"The Seventh: the One Who Kept the Rules","body":"The seventh coming-down is Rama, and his story is not a story in this shelf — it is a whole book, twenty-four nights of it, waiting for you under The Ramayana.","art":"art/story/dv-rama.jpg","cta":"Read the story","why":"From The Ten Avatars"},"st-dv.krishna":{"id":"st-dv.krishna","src":"story:dv.krishna:scenes:0:text","route":"#/story/dv.krishna","title":"The Eighth: the One Who Would Not Be Serious","body":"The eighth comes down as a baby, in a prison, on a night of pouring rain, and is carried across a flooded river to safety in a cowherd village. And then he does something none of the others do. He stays a child, and he is naughty.","art":"art/story/dv-krishna.jpg","cta":"Read the story","why":"From The Ten Avatars"},"st-dv.kalki":{"id":"st-dv.kalki","src":"story:dv.kalki:scenes:0:text","route":"#/story/dv.kalki","title":"The Tenth, Who Has Not Come Yet","body":"Every story you have read in this collection happened, in the telling — a fish came, a tortoise held, a boy took three steps. This one has not. The tenth is still ahead.","art":"art/story/dv-kalki.jpg","cta":"Read the story","why":"From The Ten Avatars"},"st-ds.who-are-the-asuras":{"id":"st-ds.who-are-the-asuras","src":"story:ds.who-are-the-asuras:scenes:0:text","route":"#/story/ds.who-are-the-asuras","title":"The Word That Does Not Mean Demon","body":"You are about to read a shelf of stories where devas and asuras are on opposite sides. So before anything else, one correction — because if you get this wrong, every story afterwards goes wrong with it.","art":"art/story/ds-who-are-the-asuras.jpg","cta":"Read the story","why":"From Devas & Asuras"},"st-ds.samudra-manthan":{"id":"st-ds.samudra-manthan","src":"story:ds.samudra-manthan:scenes:0:text","route":"#/story/ds.samudra-manthan","title":"The Day Both Sides Pulled the Same Rope","body":"The devas had lost their strength — the stories give different reasons, and every teller has a favourite. What they agree on is the fix: at the bottom of the ocean of milk lay amrita, the nectar that ends dying. And an ocean does not give things up for the asking.","art":"art/story/ds-samudra-manthan.jpg","cta":"Read the story","why":"From Devas & Asuras"},"st-ds.prahlada":{"id":"st-ds.prahlada","src":"story:ds.prahlada:scenes:0:text","route":"#/story/ds.prahlada","title":"The Boy Who Would Not Change His Mind","body":"Hiranyakashipu had made himself very nearly impossible to harm, and he ruled accordingly. There was one rule above all others in his empire: the name of Vishnu was not to be spoken.","art":"art/story/ds-prahlada.jpg","cta":"Read the story","why":"From Devas & Asuras"},"st-ds.tarakasura":{"id":"st-ds.tarakasura","src":"story:ds.tarakasura:scenes:0:text","route":"#/story/ds.tarakasura","title":"Only a Child Not Yet Born","body":"Tarakasura asked for a boon with a very neat shape to it: that he could be defeated only by a son of Shiva. And at the time he asked, Shiva had no son, was not going to have one, and was sitting in the mountains with his eyes shut, some way past caring.","art":"art/story/ds-tarakasura.jpg","cta":"Read the story","why":"From Devas & Asuras"},"st-ds.shukracharya":{"id":"st-ds.shukracharya","src":"story:ds.shukracharya:scenes:0:text","route":"#/story/ds.shukracharya","title":"The Teacher Who Could Bring Anyone Back","body":"Shukracharya was the guru of the asuras, and he was one of the great scholars of any age. He had also, through immense effort, come to know the Sanjivani vidya — the knowledge that brings the dead back to life.","art":"art/story/ds-shukracharya.jpg","cta":"Read the story","why":"From Devas & Asuras"},"st-ds.bhasmasura":{"id":"st-ds.bhasmasura","src":"story:ds.bhasmasura:scenes:0:text","route":"#/story/ds.bhasmasura","title":"The Gift He Wanted to Try Out","body":"Bhasmasura did an enormous amount of hard work — years of it — and Shiva, who is famously easy to please and famously bad at asking follow-up questions, offered him a boon.","art":"art/story/ds-bhasmasura.jpg","cta":"Read the story","why":"From Devas & Asuras"},"st-ds.banasura":{"id":"st-ds.banasura","src":"story:ds.banasura:scenes:0:text","route":"#/story/ds.banasura","title":"The Asura Who Guarded His Daughter Too Well","body":"Banasura was Mahabali’s son, and like his father he was a king, and like his grandfather Prahlada he was devoted — in his case to Shiva. The stories say he had a thousand arms, and that he used them to play the drums while Shiva danced, which is the detail everybody remembers.","art":"art/story/ds-banasura.jpg","cta":"Read the story","why":"From Devas & Asuras"},"st-ds.andhaka-gift":{"id":"st-ds.andhaka-gift","src":"story:ds.andhaka-gift:scenes:0:text","route":"#/story/ds.andhaka-gift","title":"The Asura Who Asked to Be Remembered","body":"Here is a small one that people often miss, and it says more about how these stories work than any of the big battles do.","art":"art/story/ds-andhaka-gift.jpg","cta":"Read the story","why":"From Devas & Asuras"},"ep-ramayana-1":{"id":"ep-ramayana-1","src":"epic:ramayana:episodes:0:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":1},"title":"The Ramayana · The King Who Wanted Sons","body":"On a river called the Sarayu there was a city called Ayodhya, and people who had seen a great many cities said there was nothing anywhere like it. The streets were watered twice a day so the dust would not rise. Nobody in it was hungry, and its king was called Dasharatha.","art":null,"cta":"Hear this night","why":"The Ramayana, night 1"},"ep-ramayana-2":{"id":"ep-ramayana-2","src":"epic:ramayana:episodes:1:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":2},"title":"The Ramayana · The Sage Who Asked for a Boy","body":"The sage was Vishwamitra, who had been a king himself once and had given it up, and who was known for two things: knowing more than anyone alive, and having a temper you could hear coming. \"I am trying to complete a fire ceremony in the forest,\" he said.","art":null,"cta":"Hear this night","why":"The Ramayana, night 2"},"ep-ramayana-3":{"id":"ep-ramayana-3","src":"epic:ramayana:episodes:2:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":3},"title":"The Ramayana · The Stone That Was Waiting","body":"Half a day from Mithila the path went past a garden that had gone wild — fruit trees gone to seed, a well with no rope, a house with the roof fallen in. Nobody had lived there for a very long time, and the birds went round it rather than over it.","art":null,"cta":"Hear this night","why":"The Ramayana, night 3"},"ep-ramayana-4":{"id":"ep-ramayana-4","src":"epic:ramayana:episodes:3:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":4},"title":"The Ramayana · The Bow Nobody Could Lift","body":"King Janaka of Mithila was famous for two things. The first was that he would rather talk about a difficult question than eat.","art":null,"cta":"Hear this night","why":"The Ramayana, night 4"},"ep-ramayana-5":{"id":"ep-ramayana-5","src":"epic:ramayana:episodes:4:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":5},"title":"The Ramayana · The Night Before the Crown","body":"Dasharatha was very old by now. He had begun to notice grey in his own reflection and to lose the thread of what he was saying, and one morning he called the council and said the thing everybody had been waiting years for. \"Tomorrow. Rama.","art":null,"cta":"Hear this night","why":"The Ramayana, night 5"},"ep-ramayana-6":{"id":"ep-ramayana-6","src":"epic:ramayana:episodes:5:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":6},"title":"The Ramayana · Two Old Promises","body":"Dasharatha came looking for her at midnight, happy and slightly out of breath, and found the jewellery on the floor of the corridor and his youngest queen face down in the dark room with her hair loose.","art":null,"cta":"Hear this night","why":"The Ramayana, night 6"},"ep-ramayana-7":{"id":"ep-ramayana-7","src":"epic:ramayana:episodes:6:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":7},"title":"The Ramayana · I Am Coming With You","body":"\"You are staying,\" said Rama. \"Fourteen years. Thorns, snakes, no roof, no floor, walking all day and sleeping on stone. You have never been hungry in your life. Wait for me here and look after my mother.\"","art":null,"cta":"Hear this night","why":"The Ramayana, night 7"},"ep-ramayana-8":{"id":"ep-ramayana-8","src":"epic:ramayana:episodes:7:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":8},"title":"The Ramayana · Bharata and the Sandals","body":"Dasharatha died on the sixth night, in the dark, holding Kausalya's hand and talking about a mistake he had made when he was a young man with a bow. He had said all his life that he would not survive being parted from Rama, and he had not been exaggerating.","art":null,"cta":"Hear this night","why":"The Ramayana, night 8"},"ep-ramayana-9":{"id":"ep-ramayana-9","src":"epic:ramayana:episodes:8:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":9},"title":"The Ramayana · The Years in the Forest","body":"They went south. Not in one journey — in a hundred small ones, staying a season here and a year there, at one hermitage and then the next, until the country they had grown up in was a place they talked about rather than a place they could point to.","art":null,"cta":"Hear this night","why":"The Ramayana, night 9"},"ep-ramayana-10":{"id":"ep-ramayana-10","src":"epic:ramayana:episodes:9:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":10},"title":"The Ramayana · Shurpanakha","body":"Her name was Shurpanakha, and she was a princess of the rakshasas, and the deep forest on that side of the Godavari had been her family's for a very long time. She came out of the trees, looked at Rama, and said, \"Who are you and why are you living in my woods?\"","art":null,"cta":"Hear this night","why":"The Ramayana, night 10"},"ep-ramayana-11":{"id":"ep-ramayana-11","src":"epic:ramayana:episodes:10:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":11},"title":"The Ramayana · The Golden Deer","body":"Ravana did not go himself at first. He went to an old rakshasa named Maricha, who had met Rama once before, out at Vishwamitra's fire ceremony, and had been thrown a considerable distance into the sea and had never entirely got over it.","art":null,"cta":"Hear this night","why":"The Ramayana, night 11"},"ep-ramayana-12":{"id":"ep-ramayana-12","src":"epic:ramayana:episodes:11:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":12},"title":"The Ramayana · Jatayu","body":"His name was Jatayu. He was enormous, and extremely old, and he had known Dasharatha when they were both young, and he had appointed himself the watchman of that stretch of forest without telling anyone, which is the only kind of watchman worth having.","art":null,"cta":"Hear this night","why":"The Ramayana, night 12"},"ep-ramayana-13":{"id":"ep-ramayana-13","src":"epic:ramayana:episodes:12:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":13},"title":"The Ramayana · The Berries Shabari Kept","body":"They walked south for weeks. Somewhere on the way they came round a shoulder of hill onto a path that had been swept. Not tidied — swept, properly, with a broom, every leaf, all the way up the slope, and flowers laid along both edges of it, and none of them fresh.","art":null,"cta":"Hear this night","why":"The Ramayana, night 13"},"ep-ramayana-14":{"id":"ep-ramayana-14","src":"epic:ramayana:episodes:13:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":14},"title":"The Ramayana · Two Brothers on a Mountain","body":"The monk listened to their whole story and then stopped being a monk. He grew about four feet, took his own shape, and put his head on the ground at Rama's feet. \"Hanuman,\" he said. \"Son of the wind. Minister to Sugriva, who is up on that hill and has lost his kingdom too.","art":null,"cta":"Hear this night","why":"The Ramayana, night 14"},"ep-ramayana-15":{"id":"ep-ramayana-15","src":"epic:ramayana:episodes:14:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":15},"title":"The Ramayana · The Search","body":"The rains came down for four months. Rama and Lakshmana sat them out in a cave on the hill, and Rama watched the water come off the rocks and did not sleep much, and every day Sugriva did not send word.","art":null,"cta":"Hear this night","why":"The Ramayana, night 15"},"ep-ramayana-16":{"id":"ep-ramayana-16","src":"epic:ramayana:episodes:15:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":16},"title":"The Ramayana · The Leap","body":"He climbed the mountain at the water's edge first, because he needed something to push off. The vanaras got out of the way. He stood on the top and breathed in until the trees on that mountain bent towards him, and the rock started cracking under his feet.","art":null,"cta":"Hear this night","why":"The Ramayana, night 16"},"ep-ramayana-17":{"id":"ep-ramayana-17","src":"epic:ramayana:episodes:16:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":17},"title":"The Ramayana · The Ring in the Ashoka Grove","body":"He went through Lanka house by house. Kitchens, courtyards, roof gardens, stables, libraries — and he kept catching himself admiring it. The drains worked. The lamps were beautiful. Somebody had planned this city properly and he wished, on the whole, that they had not.","art":null,"cta":"Hear this night","why":"The Ramayana, night 17"},"ep-ramayana-18":{"id":"ep-ramayana-18","src":"epic:ramayana:episodes:17:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":18},"title":"The Ramayana · The Burning Tail","body":"He started with the garden, and he was thorough. By sunrise the most beautiful grove in Lanka looked as though a hill had rolled through it — everything except the one simsupa tree Sita was sitting under, which he went round very carefully.","art":null,"cta":"Hear this night","why":"The Ramayana, night 18"},"ep-ramayana-19":{"id":"ep-ramayana-19","src":"epic:ramayana:episodes:18:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":19},"title":"The Ramayana · The Council at Lanka","body":"It has to be said properly, once, or none of the rest of it works. Ravana was not a stupid man and he was not a monster in a story. He was a scholar of the Vedas. He was a musician good enough that people still argue about which instrument he invented.","art":null,"cta":"Hear this night","why":"The Ramayana, night 19"},"ep-ramayana-20":{"id":"ep-ramayana-20","src":"epic:ramayana:episodes:19:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":20},"title":"The Ramayana · The Bridge","body":"Rama sat down on the shore facing the water and asked the sea, politely, for a way across. He sat there one day. He sat there two days. He sat there three, without eating, while behind him an entire army pretended not to be watching.","art":null,"cta":"Hear this night","why":"The Ramayana, night 20"},"ep-ramayana-21":{"id":"ep-ramayana-21","src":"epic:ramayana:episodes:20:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":21},"title":"The Ramayana · The Long Nights","body":"They camped in front of Lanka and Rama sent one more message before anything began — Angada, up over the wall, into the hall, with the same offer for the last time: give her back and keep everything. Ravana threw him out. So then there was a war, and it was not a short one.","art":null,"cta":"Hear this night","why":"The Ramayana, night 21"},"ep-ramayana-22":{"id":"ep-ramayana-22","src":"epic:ramayana:episodes:21:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":22},"title":"The Ramayana · Ravana","body":"Mandodari caught him at the door of the hall on the last morning, in his armour, and stood in front of him. \"Even now,\" she said. \"Even this morning. Walk out with her and put her hand in his and it is over by lunchtime and you are still king of this city.\"","art":null,"cta":"Hear this night","why":"The Ramayana, night 22"},"ep-ramayana-23":{"id":"ep-ramayana-23","src":"epic:ramayana:episodes:22:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":23},"title":"The Ramayana · The Fire, and the Lamps of Ayodhya","body":"They washed her hair and found her clean clothes and put her in a palanquin, and carried her out towards the camp, and the whole army came running to see her — vanaras standing on each other's shoulders, bears at the back, everybody.","art":null,"cta":"Hear this night","why":"The Ramayana, night 23"},"ep-ramayana-24":{"id":"ep-ramayana-24","src":"epic:ramayana:episodes:23:cards:0:text","route":"#/epic/ramayana","act":{"a":"episode","id":"ramayana","n":24},"title":"The Ramayana · The Book That Comes After","body":"For a while it was everything everybody had wanted. Rama was king and was good at it. Bharata slept in a bed again. Hanuman would not leave and nobody asked him to. And Sita was expecting twins, and the city was pleased about that too.","art":null,"cta":"Hear this night","why":"The Ramayana, night 24"},"ep-mahabharata-1":{"id":"ep-mahabharata-1","src":"epic:mahabharata:episodes:0:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":1},"title":"The Mahabharata · The Poet Who Needed a Scribe","body":"There was a poet called Vyasa, and he had a poem in his head that would not fit inside anybody's mouth. It was about his own family.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 1"},"ep-mahabharata-2":{"id":"ep-mahabharata-2","src":"epic:mahabharata:episodes:1:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":2},"title":"The Mahabharata · The River Who Married a King","body":"King Shantanu of Hastinapura was walking by the Ganga one morning when he saw a woman standing in the shallow water, and he stopped walking, and that was more or less that.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 2"},"ep-mahabharata-3":{"id":"ep-mahabharata-3","src":"epic:mahabharata:episodes:2:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":3},"title":"The Mahabharata · The Terrible Promise","body":"Years later, by a different stretch of water, Shantanu met a ferryman's daughter called Satyavati, and stopped walking again. He went to her father and asked for her.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 3"},"ep-mahabharata-4":{"id":"ep-mahabharata-4","src":"epic:mahabharata:episodes:3:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":4},"title":"The Mahabharata · The Boy in the Basket","body":"In a kingdom to the south, a girl called Pritha was given the job of looking after guests. One of the guests was a sage with a famously short temper, and she looked after him so well, for so long, that he went away pleased — which almost never happened.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 4"},"ep-mahabharata-5":{"id":"ep-mahabharata-5","src":"epic:mahabharata:episodes:4:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":5},"title":"The Mahabharata · A Hundred and Five Cousins","body":"Satyavati got her wish and her sons got the throne, and then both of them died young without children, and the family that Bhishma had given up everything to protect was suddenly one generation from ending.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 5"},"ep-mahabharata-6":{"id":"ep-mahabharata-6","src":"epic:mahabharata:episodes:5:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":6},"title":"The Mahabharata · The Cousins Who Could Not Be Friends","body":"Bhima was the difficulty. Not because he was cruel — because he was fourteen and built like a door and did not know his own strength, and he thought a hundred cousins was the funniest thing that had ever happened to him.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 6"},"ep-mahabharata-7":{"id":"ep-mahabharata-7","src":"epic:mahabharata:episodes:6:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":7},"title":"The Mahabharata · The Ring in the Well","body":"The princes were playing outside the walls when the ball went down a well. It was a deep, dry, old well, and they lay on their stomachs round the rim, a hundred and five of them, and achieved absolutely nothing for a very long time.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 7"},"ep-mahabharata-8":{"id":"ep-mahabharata-8","src":"epic:mahabharata:episodes:7:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":8},"title":"The Mahabharata · Ekalavya","body":"A boy came out of the forest to Drona's school. His father was the head of a forest people who lived beyond the fields, and his name was Ekalavya, and he had walked a long way.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 8"},"ep-mahabharata-9":{"id":"ep-mahabharata-9","src":"epic:mahabharata:episodes:8:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":9},"title":"The Mahabharata · The Young Man at the Gate","body":"They built an arena outside Hastinapura and the whole city came — Bhishma in the front row with Dhritarashtra beside him, Kunti and Gandhari up in the covered gallery, and not a spare inch of ground anywhere. Yudhishthira was elegant with a spear, and the twins rode.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 9"},"ep-mahabharata-10":{"id":"ep-mahabharata-10","src":"epic:mahabharata:episodes:9:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":10},"title":"The Mahabharata · The House Made of Lac","body":"After the tournament the city made its feelings clear, loudly, in the streets: make Yudhishthira the crown prince. He was the eldest of that generation. He was fair. People liked him.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 10"},"ep-mahabharata-11":{"id":"ep-mahabharata-11","src":"epic:mahabharata:episodes:10:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":11},"title":"The Mahabharata · The Fish in the Water","body":"King Drupada — yes, that Drupada, Drona's old friend — had a daughter called Draupadi, and he set a contest for her that was designed so that exactly one man in the world could win it.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 11"},"ep-mahabharata-12":{"id":"ep-mahabharata-12","src":"epic:mahabharata:episodes:11:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":12},"title":"The Mahabharata · The Hall With Floors Like Water","body":"Dhritarashtra split the kingdom. The brothers got the half that was scrub and rock and old forest, with no city on it and nothing growing, and the family kept Hastinapura. Yudhishthira said thank you and went, and Bhima did not speak for a week.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 12"},"ep-mahabharata-13":{"id":"ep-mahabharata-13","src":"epic:mahabharata:episodes:12:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":13},"title":"The Mahabharata · The Game","body":"The invitation came from Dhritarashtra, an uncle to a nephew, and it was for a friendly game in the new hall at Hastinapura. Vidura carried it, and hated carrying it, and said so on the way in and was told to be quiet.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 13"},"ep-mahabharata-14":{"id":"ep-mahabharata-14","src":"epic:mahabharata:episodes:13:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":14},"title":"The Mahabharata · Draupadi's Question","body":"The messenger went to the women's rooms and told her, and she did not scream and did not weep. She asked him a question and sent him back with it, and the question is the sharpest thing in the whole poem.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 14"},"ep-mahabharata-15":{"id":"ep-mahabharata-15","src":"epic:mahabharata:episodes:14:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":15},"title":"The Mahabharata · One More Throw","body":"They were on the road. The chariots were loaded. The kingdom had been handed back, the brothers were free, and for about an hour it looked as if the whole disaster was going to end in an apology and a long silence at family dinners.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 15"},"ep-mahabharata-16":{"id":"ep-mahabharata-16","src":"epic:mahabharata:episodes:15:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":16},"title":"The Mahabharata · The Longest Argument in the Forest","body":"The Vana Parva is the longest book in the whole poem, and almost nothing happens in it. Twelve years of walking, and camping, and listening to other people's stories, and having the same argument over and over again around a fire.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 16"},"ep-mahabharata-17":{"id":"ep-mahabharata-17","src":"epic:mahabharata:episodes:16:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":17},"title":"The Mahabharata · The Hunter on the Mountain","body":"Arjuna went north by himself, up past the snow line, to ask for weapons they were going to need. He stood on one leg for a long time and ate almost nothing and did not speak, and the mountain took its time about noticing.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 17"},"ep-mahabharata-18":{"id":"ep-mahabharata-18","src":"epic:mahabharata:episodes:17:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":18},"title":"The Mahabharata · What Karna Would Not Refuse","body":"Karna had a rule, and the whole country knew it. After his morning prayers at the water, he did not refuse anybody anything. Whatever you asked for, if you asked him then, you got it.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 18"},"ep-mahabharata-19":{"id":"ep-mahabharata-19","src":"epic:mahabharata:episodes:18:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":19},"title":"The Mahabharata · The Voice in the Lake","body":"Late in the twelve years they were deep in dry country, chasing a deer that had run off with a holy man's fire sticks, and they lost it, and then they lost the water, and then they were in real trouble.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 19"},"ep-mahabharata-20":{"id":"ep-mahabharata-20","src":"epic:mahabharata:episodes:19:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":20},"title":"The Mahabharata · The Year Nobody Knew Them","body":"The thirteenth year had to be spent somewhere in the world where nobody recognised them. If anyone did, the whole thirteen started again. So they picked the court of an old king called Virata, walked in through the front door, and asked for jobs.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 20"},"ep-mahabharata-21":{"id":"ep-mahabharata-21","src":"epic:mahabharata:episodes:20:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":21},"title":"The Mahabharata · The Prince Who Ran Away","body":"Duryodhana had worked out roughly where they must be, and came to raid Virata's cattle partly for the cattle and mostly to flush them out before the thirteenth year ended. The whole family came: Bhishma, Drona, Karna, all of them.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 21"},"ep-mahabharata-22":{"id":"ep-mahabharata-22","src":"epic:mahabharata:episodes:21:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":22},"title":"The Mahabharata · Both Cousins Come Asking","body":"Everybody now went looking for allies, and the two cousins had the same idea on the same day, which is how they both ended up in Krishna's room in Dwaraka while he was asleep.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 22"},"ep-mahabharata-23":{"id":"ep-mahabharata-23","src":"epic:mahabharata:episodes:22:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":23},"title":"The Mahabharata · Five Villages","body":"Krishna went to Hastinapura himself, as a messenger, to try to stop it. The whole city came out onto the road to see him come in, which tells you how badly ordinary people wanted this not to happen.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 23"},"ep-mahabharata-24":{"id":"ep-mahabharata-24","src":"epic:mahabharata:episodes:23:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":24},"title":"The Mahabharata · Kunti at the Water","body":"Karna prayed at the water every morning, facing the sun, and did not turn round for anybody until he had finished. So Kunti stood behind him in the heat, in the open, and waited, and he did not know she was there.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 24"},"ep-mahabharata-25":{"id":"ep-mahabharata-25","src":"epic:mahabharata:episodes:24:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":25},"title":"The Mahabharata · The Night Before","body":"Kurukshetra is flat, and dry, and enormous, and by the end of that week there were eighteen armies camped on it — eleven on one side and seven on the other, which tells you how the odds looked to anybody counting tents.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 25"},"ep-mahabharata-26":{"id":"ep-mahabharata-26","src":"epic:mahabharata:episodes:25:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":26},"title":"The Mahabharata · A Talk Between Friends","body":"The chariot stopped in the middle, between the two lines, with everybody watching. And Arjuna, who had wanted this war for thirteen years, stood up and looked along the other side properly for the first time.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 26"},"ep-mahabharata-27":{"id":"ep-mahabharata-27","src":"epic:mahabharata:episodes:26:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":27},"title":"The Mahabharata · The Fall of Bhishma","body":"For nine days Bhishma held the whole field. He was old enough to be everybody's grandfather and there was nothing anybody on the other side could do about him, and every evening Yudhishthira came back to his tent and sat with his head in his hands.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 27"},"ep-mahabharata-28":{"id":"ep-mahabharata-28","src":"epic:mahabharata:episodes:27:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":28},"title":"The Mahabharata · The Boy Inside the Wheel","body":"On the thirteenth day Drona set out a formation shaped like a turning wheel, with the army spiralling inward, and there were only two men on the other side who knew how to break into it — Krishna and Arjuna.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 28"},"ep-mahabharata-29":{"id":"ep-mahabharata-29","src":"epic:mahabharata:episodes:28:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":29},"title":"The Mahabharata · Three Words in a Loud Room","body":"By the fifteenth day Drona could not be stopped. He was old, and he was the best teacher of weapons who had ever lived, and he was going through the army he had taught like a man mowing.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 29"},"ep-mahabharata-30":{"id":"ep-mahabharata-30","src":"epic:mahabharata:episodes:29:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":30},"title":"The Mahabharata · The Wheel in the Mud","body":"Karna took command, and he had one day and a night of it, and he was every bit as good as everybody had always been afraid he was.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 30"},"ep-mahabharata-31":{"id":"ep-mahabharata-31","src":"epic:mahabharata:episodes:30:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":31},"title":"The Mahabharata · The Last Day","body":"On the eighteenth day there was almost nothing left of either army, and Duryodhana was alone. Every one of his brothers was gone. Bhishma was lying on his arrows. Drona was gone. Karna was gone. Shakuni, who had started it, was gone.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 31"},"ep-mahabharata-32":{"id":"ep-mahabharata-32","src":"epic:mahabharata:episodes:31:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":32},"title":"The Mahabharata · Gandhari Counts","body":"This is the shortest book in the poem and it is the one people cannot read out loud. The fighting is over. The women come out of Hastinapura at first light and walk onto the field, and the poem hands them the whole story and stands back.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 32"},"ep-mahabharata-33":{"id":"ep-mahabharata-33","src":"epic:mahabharata:episodes:32:cards:0:text","route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":33},"title":"The Mahabharata · The Dog at the Gate","body":"They ruled for a long time, and it was fine, and it was quiet, and nobody in the palace ever quite got the field out of their head. And then one morning they took off the crowns, left them on a chair, and walked out of the city going north, with Draupadi, on foot.","art":null,"cta":"Hear this night","why":"The Mahabharata, night 33"}});
